const e={lerninhalte:{"unternehmer-firma-firmenbuch":{schritte:[{titel:"Who is an entrepreneur?",blocks:[{type:"begriff",term:"Entrepreneur (UGB)",erklaerung:"Someone who runs a business alone or with others."},{type:"begriff",term:"Business",erklaerung:"Any permanent organisation with independent economic activity – even if it is not aimed at profit."},{type:"vergleich",links:{titel:"Natural persons",punkte:["Living people","e.g. sole proprietor"]},rechts:{titel:"Legal persons",punkte:["Organisations founded by law (e.g. GmbH, AG)","Same rights & duties","Represented by people = bodies"]}},{type:"merke",text:"Farmers and foresters, liberal professions (doctor, lawyer) and new self-employed (artists) also count as entrepreneurs."}]},{titel:"What is a company name (Firma)?",blocks:[{type:"begriff",term:"Company name (Firma)",erklaerung:"The name entered in the company register under which the entrepreneur does business, signs, and sues or is sued."},{type:"kette",glieder:[{titel:"freely chosen",wert:"Core name"},{titel:"Legal form",wert:"+ legal form suffix"},{titel:"Example",wert:"Red Bull GmbH"}]},{type:"tabelle",spalten:["Type","Meaning","Example"],zeilen:[["Personal name","Name of the entrepreneur","Thomas Radler e. U."],["Descriptive name","Refers to the business purpose","Österreichische Post AG"],["Invented name","made-up name","Red Bull GmbH"],["Mixed name","mixture","Max Steindl Immobilien OG"]]},{type:"tabelle",spalten:["Rule","Meaning"],zeilen:[["Suitability as a name","readable, pronounceable, works as a name"],["Distinctiveness","must clearly differ from company names in the same place (e.g. “Karl Huber jun. e. U.”)"],["Ban on misleading names","no false information (no “car” if only motorbikes)"]]},{type:"merke",text:"When a business is bought/inherited, the old company name may be continued if the former owner agrees. Not in the company register → business designation instead of company name."}]},{titel:"Company register",blocks:[{type:"begriff",term:"Company register",erklaerung:"Public electronic register with the most important information about companies. Kept by the company register courts."},{type:"vergleich",links:{titel:"Registration compulsory",punkte:["Sole proprietorships from €1 million turnover (or 2 years at €700,000 each)","Corporations (GmbH, AG)","Partnerships (OG, KG)","Cooperatives"]},rechts:{titel:"Registration voluntary",punkte:["Smaller sole proprietorships","Liberal professions","Agriculture and forestry (sole proprietors)"]}},{type:"vergleich",frage:"The company register consists of:",links:{titel:"Main register",punkte:["Company name, company register number","Legal form, registered office, line of business","Owner/partners","Date of registration"]},rechts:{titel:"Collection of documents",punkte:["Articles of association","Specimen signatures","Balance sheet","Shareholder resolutions"]}},{type:"begriff",term:"Publication & inspection",erklaerung:"New entries appear in the Ediktsdatei and on the EVI. Anyone can request an extract from the company register (court, notary, lawyer or online)."},{type:"merke",text:"Registered companies must state the company name, legal form, register number, register court and registered office in letters, e-mails and the legal notice. The entry protects the company name."}]}],zusammenfassung:[{titel:"Entrepreneur",punkte:["Entrepreneur = runs a business (permanent, independent, economic)","Natural persons (people) ↔ legal persons (organisations, represented by bodies)"]},{titel:"Company name",punkte:["Company name = name in the company register = core name + legal form suffix","Personal, descriptive, invented, mixed name","Rules: suitability as a name, distinctiveness, ban on misleading names","Can be continued on acquisition with consent"]},{titel:"Company register",punkte:["Public electronic register, kept by company register courts","Compulsory: sole proprietorships > €1 million/2× €700,000, OG, KG, GmbH, AG, cooperative","Main register (data) + collection of documents","Publication: Ediktsdatei, EVI · anyone can inspect it"]}]},"rechtsformen-unternehmen":{schritte:[{titel:"Criteria & overview",blocks:[{type:"tabelle",spalten:["Criterion","Question"],zeilen:[["Number of owners","Alone or with partners?"],["Raising capital","Is there a minimum capital?"],["Liability","Who is liable for debts, and how?"],["Management/control","Who manages, who controls?"],["Distribution of profit","Who gets the profit/bears the loss?"],["Type of bookkeeping","Cash-based or double-entry?"],["Income tax burden","How much tax, paid by whom?"]]},{type:"tabelle",spalten:["Type of liability","Meaning"],zeilen:[["Limited (partial liability)","only up to a certain amount (liability sum)"],["Unlimited (full liability)","including all private assets"],["Direct","creditor can go straight to the partner"],["Joint and several","each is liable for ALL debts; the creditor chooses"]]},{type:"tabelle",spalten:["Group","Legal forms","Focus"],zeilen:[["Sole proprietorship","e. U. / not registered","1 person"],["Partnerships","OG, KG, silent partnership, GesbR","personal involvement"],["Corporations","GmbH, AG, FlexKapG","pooled capital"],["Special form","Cooperative","Supporting the members"],["Mixed form","GmbH & Co KG","Advantages combined"]]},{type:"tabelle",spalten:["Form","Income tax"],zeilen:[["Sole proprietor","income tax (up to 55%)"],["Partnership","partners pay income tax"],["Corporation","company 23% corporate tax + shareholders 27.5% capital gains tax on distributions"]]},{type:"merke",text:"Death/bankruptcy of a partner dissolves sole proprietorships and partnerships – NOT corporations and cooperatives."}]},{titel:"Sole proprietorship",blocks:[{type:"begriff",term:"Sole proprietorship",erklaerung:"One person is the sole owner. Created when the trade is registered. Most common legal form (over 70%)."},{type:"tabelle",spalten:["Criterion","Rule"],zeilen:[["Capital","no minimum capital"],["Liability","fully liable: personally, without limit"],["Management","alone"],["Profit","profit and loss alone"],["Tax","income tax"],["Company register","compulsory from €1 million (2× €700,000) → e. U."]]},{type:"vergleich",links:{titel:"Advantages",punkte:["Quick, simple set-up","No minimum capital","Profit not shared","Freedom to decide"]},rechts:{titel:"Disadvantages",punkte:["Unlimited liability","A lot of responsibility","No one to stand in during illness","Borrowing is difficult"]}}]},{titel:"OG & KG",blocks:[{type:"tabelle",spalten:["","General partnership (OG)","Limited partnership (KG)"],zeilen:[["Founders","at least 2 fully liable partners","at least 1 general partner (fully liable) + 1 limited partner (partially liable)"],["Founding","partnership agreement + company register","partnership agreement + company register"],["Minimum capital","none","none"],["Liability","all personally, unlimited, direct, joint and several","general partner like OG; limited partner only up to the liability sum"],["Management","all partners","general partners; limited partner only has a right of control"],["Profit","according to partnership agreement (otherwise UGB)","according to partnership agreement"],["Tax","partners pay income tax","partners pay income tax"]]},{type:"begriff",term:"Non-compete clause",erklaerung:"An OG partner (or general partner) may not do business in the same line of business without consent."},{type:"merke",text:"Anyone who leaves an OG is still liable for old debts for 5 years. The KG suits when one person wants to work and another only wants to contribute money."}]},{titel:"Silent partnership & GesbR",blocks:[{type:"begriff",term:"Silent partnership",erklaerung:"Contractual participation of a silent partner with a capital contribution in an existing company. Not a separate legal form, not in the company register – invisible to the outside world."},{type:"vergleich",links:{titel:"Silent partner",punkte:["Liable only up to the contribution","No management, only a right of control","Shares in profit, loss at most up to the contribution","Tax: income tax"]},rechts:{titel:"Advantage for the company",punkte:["Capital and know-how","Without sharing the management"]}},{type:"begriff",term:"Civil law partnership (GesbR)",erklaerung:"At least 2 people/companies with a common purpose. Not in the company register, no minimum capital, all are liable without limit, jointly and severally.",beispiel:"Consortium for a construction project (motorway, wind farm)"},{type:"merke",text:"If a GesbR exceeds the turnover limits, it must be converted into an OG or KG."}]},{titel:"GmbH",blocks:[{type:"begriff",term:"Corporation",erklaerung:"Legal person with its own legal personality: can acquire rights, conclude contracts, sue and be sued."},{type:"tabelle",spalten:["Criterion","GmbH (private limited company)"],zeilen:[["Founders","at least 1 person, articles of association"],["Founding","traditional (notarial deed) or simplified (single-person GmbH online)"],["Share capital","at least €10,000, half in cash immediately; capital contribution at least €70"],["Liability","GmbH with company assets; shareholders only up to their contribution"],["Tax","23% corporate tax (incl. minimum) + 27.5% capital gains tax on distribution ≈ 44.175%"]]},{type:"organe",oben:{name:"General meeting",punkte:["All shareholders","At least once a year","Voting rights according to contribution","Decides on distribution of profit"]},links:{name:"Supervisory board",punkte:["Controls the management","Only compulsory above €70,000 capital and > 50 shareholders or > 300 employees"]},rechts:{name:"Managing director",punkte:["At least 1 natural person","Management & representation","Annual financial statements","Calls the general meeting"]},pfeile:{links:"elects",rechts:"appoints",unten:"Supervisory board → controls → managing director"}},{type:"begriff",term:"Reserves & obligation to make additional contributions",erklaerung:"Reserves = retained profits. Obligation to make additional contributions = extra payments by shareholders in case of losses (if agreed in the contract)."},{type:"vergleich",links:{titel:"Advantages",punkte:["Liability limited to the contribution","Can be founded by 1 person","No non-compete clause for pure investors","Lower tax on high profits"]},rechts:{titel:"Disadvantages",punkte:["High set-up costs","Complex founding process","Always required to draw up a balance sheet","Limited creditworthiness"]}}]},{titel:"AG",blocks:[{type:"tabelle",spalten:["Criterion","Public limited company (AG)"],zeilen:[["Founders","at least 1 person, articles of association (notarial deed)"],["Share capital","at least €70,000, ¼ paid in on founding; by issuing shares"],["Liability","AG with share capital; shareholder only with their shares"],["Profit","General meeting decides: reserve (5% up to 10% of share capital) + dividend"],["Tax","23% corporate tax (minimum €3,500) + 27.5% capital gains tax on dividends"]]},{type:"begriff",term:"Share & dividend",erklaerung:"Share = security representing a part of the share capital. Dividend = share of profit paid out to shareholders.",beispiel:"Nominal value = share capital / number of shares"},{type:"organe",oben:{name:"General meeting",punkte:["All shareholders, at least once a year","Elects the supervisory board (max. 4 years)","Decides on the dividend","Elects the auditor"]},links:{name:"Supervisory board",punkte:["3–20 members","Appoints the management board (max. 5 years)","Controls the management board"]},rechts:{name:"Management board",punkte:["Management & representation","Annual financial statements","Dividend proposal","Calls the general meeting"]},pfeile:{links:"elects",rechts:"calls",unten:"Supervisory board → appoints & controls → management board"}},{type:"begriff",term:"Calculating the dividend",erklaerung:"Annual profit − 5% reserve = profit to be distributed. Divided by the number of shares = dividend per share.",beispiel:"300,000 − 15,000 = €285,000 / 50,000 shares = €5.70 per share"},{type:"vergleich",links:{titel:"Advantages",punkte:["A lot of capital from many shareholders","Liability limited to the shares","Shares easy to transfer (stock exchange)"]},rechts:{titel:"Disadvantages",punkte:["High set-up costs","High minimum capital","Complex founding process","High organisational effort"]}}]},{titel:"FlexKapG, GmbH & Co KG, cooperative",blocks:[{type:"begriff",term:"Flexible company (FlexKapG/FlexCo)",erklaerung:"Mix of GmbH and AG for start-ups. Minimum share capital €10,000, stakes from €1. Employees can receive company value shares (no voting rights, but a share in profit)."},{type:"kette",glieder:[{titel:"General partner",wert:"GmbH"},{titel:"+ limited partners",wert:"People"},{titel:"=",wert:"GmbH & Co KG"}]},{type:"text",text:"In a GmbH & Co KG a GmbH takes on the role of the general partner with unlimited liability → so in the end nobody is liable without limit with private assets."},{type:"begriff",term:"Cooperative (Gen)",erklaerung:"Association with an open number of members (at least 2) that supports the business or economy of its members. Must be in the company register, no minimum capital; members' liability according to the articles.",beispiel:"Organic beekeepers sell their honey together"}]}],zusammenfassung:[{titel:"Criteria",punkte:["Owners, capital, liability, management, profit, bookkeeping, tax","Liability: limited/unlimited · direct · joint and several","Tax: sole/partnership → income tax · corporation → 23% corporate tax + 27.5% capital gains tax"]},{titel:"Partnerships",punkte:["Sole proprietorship: 1 fully liable person, no minimum capital","OG: at least 2 fully liable partners, all manage, unlimited/direct/joint and several","KG: general partner (fully liable, manages) + limited partner (partially liable, control)","Silent partnership: contribution, liable up to the contribution, no management, not in the company register","GesbR: at least 2, consortium, not in the company register, all liable without limit"]},{titel:"Corporations",punkte:["GmbH: at least 1 person, €10,000 share capital, liability up to contribution; bodies: general meeting, managing director, (supervisory board)","AG: €70,000 share capital (shares), liability with shares; bodies: general meeting, supervisory board, management board","Dividend = (profit − 5% reserve) / number of shares","FlexKapG: GmbH + AG elements, start-ups, company value shares"]},{titel:"Mixed & special forms",punkte:["GmbH & Co KG: GmbH is the general partner → limited liability","Cooperative: open number of members, supports members, must be in the company register"]}]},vollmachten:{schritte:[{titel:"What is a power of attorney?",blocks:[{type:"begriff",term:"Power of attorney",erklaerung:"The authority to act on behalf of another person (power of representation). Requires trust between the person granting it and the authorised person."},{type:"vergleich",links:{titel:"Prokura (general commercial power)",punkte:["Most extensive power of attorney","Only from companies in the company register","All deals the business involves"]},rechts:{titel:"Commercial power of attorney (Handlungsvollmacht)",punkte:["Limited power of attorney","From any company","Deals that a particular business usually involves"]}}]},{titel:"Prokura",blocks:[{type:"begriff",term:"Prokura",erklaerung:"Entitles the holder to all court and out-of-court transactions of the business. Granted by express declaration (oral/written), entry in the company register is compulsory. The authorised person is called a Prokurist."},{type:"vergleich",links:{titel:"✓ A Prokurist may",punkte:["Buy and sell goods","Hire/dismiss employees","Take out loans","Grant commercial powers of attorney","Represent the company in court"]},rechts:{titel:"✗ A Prokurist may not",punkte:["Dissolve/sell the company","Change the company name","Mortgage/sell land","Sign the balance sheet","Appoint other Prokuristen/pass on the Prokura"]}},{type:"merke",text:"Internal restrictions (e.g. “no deals over €9,500”) do NOT apply to third parties: the contract is valid, but the Prokurist must pay damages and can be dismissed."},{type:"tabelle",spalten:["Type of Prokura","Authorised to represent …"],zeilen:[["Sole Prokura","alone"],["Joint Prokura","only with one or more other Prokuristen (four-eyes principle)"],["Mixed Prokura","only with a managing director or management board member"],["Branch Prokura","only for one branch"]]},{type:"begriff",term:"Signature",erklaerung:"With pp. (per procura) or ppa. (per procura autoritate) before the name.",beispiel:"ppa. Laura Trummer"},{type:"begriff",term:"End of the Prokura",erklaerung:"Revoked by the person who granted it · notice, death or legal incapacity of the Prokurist · bankruptcy of the company."}]},{titel:"Commercial power of attorney",blocks:[{type:"begriff",term:"Commercial power of attorney",erklaerung:"Entitles the holder to deals that a particular business usually involves. Granted by any entrepreneur or Prokurist – expressly or by implied conduct. Not entered in the company register.",beispiel:"Employee orders coffee beans for the 4th time, the boss pays every time → power of attorney by implied conduct"},{type:"vergleich",links:{titel:"✓ may",punkte:["Ordinary business transactions","Buy and sell goods","Pay wages and salaries"]},rechts:{titel:"✗ may not",punkte:["Everything a Prokurist is also forbidden to do","Take out loans","Represent the company in court"]}},{type:"merke",text:"Restrictions on the commercial power of attorney ALSO apply to third parties if they know (or should know) about them. Can only be passed on with consent."},{type:"tabelle",spalten:["Type","For …","Example"],zeilen:[["General power of attorney","all ordinary business of the company","Branch manager chooses the collection, hires staff"],["Power of attorney for a type of deal","one particular type of deal","Ordering goods up to €40,000"],["Special power of attorney (single)","a single action","Buying a new mirror for the changing room"]]},{type:"tabelle",spalten:["Power of attorney","Signature"],zeilen:[["Prokura","pp. / ppa."],["General power of attorney","i. V. (on behalf of)"],["Type and special power of attorney","i. A. (by order of)"]]}]}],zusammenfassung:[{titel:"Prokura",punkte:["Most extensive power of attorney; only from companies in the company register; entry compulsory","May: buy/sell, staff, loans, commercial powers of attorney, court","May not: dissolve/sell, company name, land, balance sheet, pass on Prokura","Types: sole, joint, mixed, branch Prokura","Signature pp./ppa. · internal restriction does not apply to third parties","Ends: revocation, notice/death/incapacity, bankruptcy"]},{titel:"Commercial power of attorney",punkte:["Limited: ordinary business; from any entrepreneur/Prokurist; also implied; not in the company register","May not take out loans or represent in court","General power of attorney (i. V.) · type, special power of attorney (i. A.)"]}]},beschaeftigungsverhaeltnisse:{schritte:[{titel:"Types of employment contracts",blocks:[{type:"entscheidung",titel:"Which type of employment?",schritte:[{frage:"Is a finished piece of work/result owed?",links:{antwort:"Yes",ergebnis:"Contract for work",beispiel:"Designing a website for €12,000"},rechts:{antwort:"No, labour",weiter:"keep checking"}},{frage:"Bound by instructions, working hours and place of work?",links:{antwort:"No",ergebnis:"Freelance service contract",beispiel:"Data entry from home"},rechts:{antwort:"Yes",ergebnis:"“Genuine” employment contract",beispiel:"Salaried employees, workers, apprentices"}}]},{type:"begriff",term:"“Genuine” employment contract",erklaerung:"The employee provides their personal labour at a certain place at certain times. Follows instructions, receives work equipment, bears no risk."},{type:"begriff",term:"Marginal employment",erklaerung:"Pay is below the marginal earnings threshold. Entitled to holiday, continued pay, special payments – but no social security contributions and no wage tax; only accident insurance."},{type:"begriff",term:"Freelance service contract",erklaerung:"Labour for pay, but without personal dependence: no instructions, free choice of time and place, someone else can stand in, work equipment from the employer."},{type:"begriff",term:"Contract for work",erklaerung:"Obligation to deliver a result/work. Money only if the work is done as agreed in the contract. Own work equipment, own risk, warranty."}]},{titel:"Effects compared",blocks:[{type:"tabelle",spalten:["","“Genuine” employment contract","Freelance service contract","Contract for work"],zeilen:[["Instructions","bound","not bound","not bound"],["Work equipment","from the employer","from the employer","own"],["Entitlements","wages, holiday, sick leave, special payments","only pay for services","pay on completion of the work"],["Social security","registered by the employer (ÖGK)","registered by the employer (ÖGK)","self (SVS)"],["Tax","employer pays wage tax","self (income tax return)","self"]]},{type:"merke",text:"Freelancers and contractors have NO entitlement to paid holiday, sick pay or special payments."}]}],zusammenfassung:[{titel:"Types of employment",punkte:["“Genuine” employment contract: personal labour, instructions, fixed time/place, work equipment from the employer, no risk","Entitlements: holiday, continued pay, special payments; employer registers for social security, pays wage tax","Marginal: below the marginal earnings threshold, only accident insurance, no social security/wage tax","Freelance service contract: no instructions, can be replaced; employer registers for social security, own tax; no holiday","Contract for work: result owed, own equipment and risk, own SVS insurance, own tax, warranty"]}]},"kaufvertraege-aussenhandel":{schritte:[{titel:"Importance of foreign trade",blocks:[{type:"begriff",term:"Foreign trade (international business)",erklaerung:"Exchange of goods (products and services) between different countries."},{type:"vergleich",links:{titel:"Import",punkte:["Buying abroad, using it in your own country","Buyer = importer"]},rechts:{titel:"Export",punkte:["Selling abroad","Seller = exporter"]}},{type:"tabelle",spalten:["Reason","Example"],zeilen:[["Goods are not available (enough) in your own country","Coffee from Brazil, crude oil"],["Specialisation of certain countries","Ski production in Austria"],["Overproduction","Cheese from Holland"],["Good brand image","Swarovski, Red Bull"]]},{type:"begriff",term:"Risk",erklaerung:"Danger that invested capital is lost or the planned profit is not achieved. Higher abroad: different legal systems, currencies, trade customs."}]},{titel:"Risks for the exporter",blocks:[{type:"tabelle",spalten:["Phase","Risk","Protection"],zeilen:[["BEFORE delivery","Market risk (product does not suit the market)","Market research"],["","Production risk (customer goes bankrupt/withdraws)","Down payment, payment guarantee"],["DURING delivery","Transport risk (theft, loss, damage, delay)","Incoterms, transport insurance"],["","Acceptance risk (customer does not accept the goods)","Down payment, payment guarantee, documentary credit"],["AFTER delivery","Risk of non-payment","Down payment, state export guarantee (OeKB), a bank's promise to pay"],["","Credit risk (money arrives late)","Low-interest export financing"],["","Exchange rate risk","Hedging transactions (forward exchange contract)"]]},{type:"begriff",term:"Exchange rate risk",erklaerung:"If payment is in a foreign currency, the exchange rate can fall and you receive fewer euros.",beispiel:"10,000 USD at €1 = 1 USD → rate falls to €0.90 → only €9,000"},{type:"begriff",term:"Payment guarantee",erklaerung:"A bank undertakes to pay if the foreign importer does not pay."}]},{titel:"Risks for the importer",blocks:[{type:"tabelle",spalten:["Phase","Risk","Protection"],zeilen:[["BEFORE delivery","Delivery risk (not at all, wrong, too little, too late)","small down payment, credit purchase, penalty"],["DURING","Transport risk","Incoterms, transport insurance"],["AFTER","Warranty risk","Bank guarantee"],["","Exchange rate risk","Hedging transactions"]]},{type:"merke",text:"International contracts: usually in English; as a compromise often in US dollars as a third currency."}]},{titel:"Incoterms",blocks:[{type:"begriff",term:"Incoterms",erklaerung:"International Commercial Terms – delivery clauses that determine where risk and costs pass from the seller to the buyer. Only apply if they are in the contract."},{type:"vergleich",links:{titel:"Incoterms regulate",punkte:["Transfer of risk","Transfer of costs","Who arranges means of transport/documents","Who handles export, transit, import"]},rechts:{titel:"Incoterms do NOT regulate",punkte:["Breaches of contract","Payment terms","Applicable law"]}},{type:"tabelle",spalten:["Group","Principle","Clauses"],zeilen:[["E – collection clause","Minimum clause for the seller: buyer collects ex works","EXW"],["F – main carriage unpaid","Buyer pays the main transport; handover to his carrier","FCA, FAS, FOB"],["C – main carriage paid","Seller pays the main transport, but risk passes at the 1st carrier","CPT, CIP, CFR, CIF"],["D – arrival clause","Maximum clause for the buyer: seller bears everything to the destination","DAP, DPU, DDP"]]},{type:"merke",text:"E, F, D = one-point clauses (risk + costs at the same place). C = two-point clauses (risk early, costs only at the destination)."},{type:"transportweg",titel:"CPT Graz station (seller BMW Munich)",stationen:["BMW","Munich stn.","Graz stn.","Buyer"],risiko:1,kosten:2},{type:"tabelle",spalten:["Clause","Meaning","Transport"],zeilen:[["EXW – Ex Works","everything from the seller's works","all"],["FCA – Free Carrier","handover to the 1st carrier","all"],["CPT – Carriage Paid To","risk: 1st carrier · costs: destination","all"],["CIP – Carriage and Insurance Paid To","like CPT + seller pays insurance","all"],["DAP / DPU / DDP","destination (DPU + unloaded, DDP + duty paid)","all"],["FAS – Free Alongside Ship","alongside the ship in the port of shipment","ship"],["FOB – Free On Board","after loading in the port of shipment","ship"],["CFR – Cost and Freight","risk: on board · costs: port of destination","ship"],["CIF – Cost, Insurance and Freight","like CFR + seller pays insurance","ship"]]}]},{titel:"Documents in foreign trade",blocks:[{type:"tabelle",spalten:["Means of transport","Transport document"],zeilen:[["Ship (sea)","Ocean bill of lading"],["Ship (inland waters)","Inland waterway bill of lading"],["Aircraft","Air waybill"],["Railway","International railway consignment note"],["Lorry","Road consignment note (CMR)"],["Several means of transport","FIATA Multimodal Transport Bill of Lading"]]},{type:"tabelle",spalten:["Document","Purpose"],zeilen:[["Certificate of origin","proves which country the goods come from"],["Movement certificate","duty-free/reduced duties under free trade agreements"],["Import/export licence","for special goods (e.g. with military use)"],["Pro forma invoice","before delivery, no obligation to pay – for customs/import licence"],["Commercial invoice","confirms the actual sale, for customs clearance"]]}]},{titel:"Documentary credit & collection",blocks:[{type:"begriff",term:"Documentary credit (letter of credit)",erklaerung:"Promise to pay by the importer's bank: it pays as soon as the exporter presents the documents for the goods shipped."},{type:"vergleich",links:{titel:"Protects the exporter against",punkte:["Risk of non-payment","Acceptance risk"]},rechts:{titel:"Protects the importer against",punkte:["Delivery risk (only pays if the documents are correct)"]}},{type:"ablauf",titel:"Letter of credit procedure",schritte:[{titel:"Purchase contract with letter of credit"},{titel:"Buyer instructs his bank (issuing bank)"},{titel:"Issuing bank sends notice of opening to the seller's bank (advising bank)"},{titel:"Seller is informed"},{titel:"Seller ships the goods, gives the documents to his bank"},{titel:"Seller receives his money after checking"},{titel:"Banks forward documents and settle accounts"},{titel:"Buyer pays, receives the documents → right to dispose of the goods"}]},{type:"merke",text:"Deadlines: expiry date, shipping deadline, presentation period (max. 21 days). Unconfirmed = only the buyer's bank is liable. Confirmed = the seller's bank is also liable. Only the documents are checked, not the goods!"},{type:"begriff",term:"Documentary collection",erklaerung:"The seller's bank only hands the documents to the buyer against payment (D/P) or against acceptance of a bill of exchange (D/A). Banks give NO payment guarantee."},{type:"tabelle",spalten:["","Letter of credit","Collection"],zeilen:[["Bank's payment guarantee","yes","no"],["Acceptance risk for the exporter","covered","remains"],["Suitable for","new business partners","trusted business partners"]]}]}],zusammenfassung:[{titel:"Foreign trade",punkte:["Import = buying in (importer buys) · export = selling out (exporter sells)","Reasons: shortage, specialisation, overproduction, image"]},{titel:"Risks & protection",punkte:["Exporter: market & production risk → transport & acceptance risk → non-payment, credit, exchange rate risk","Importer: delivery risk → transport risk → warranty, exchange rate risk","Protection: market research, down payment, payment guarantee, export guarantee (OeKB), export financing, Incoterms, transport insurance, hedging, penalty, bank guarantee"]},{titel:"Incoterms",punkte:["Regulate transfer of risk and costs (not payment or law)","E (EXW) · F (FCA, FAS, FOB) · C (CPT, CIP, CFR, CIF) · D (DAP, DPU, DDP)","C = two-point clause, the rest = one-point clauses","FAS, FOB, CFR, CIF only for ships; CIP/CIF: seller pays insurance"]},{titel:"Documents & payment",punkte:["Ocean bill of lading, air waybill, CMR (lorry), railway consignment note","Certificate of origin, movement certificate, pro forma invoice, commercial invoice","Documentary credit: bank pays against documents; confirmed/unconfirmed; protects both","Documentary collection: D/P (against payment) or D/A (against bill of exchange); no bank guarantee"]}]},"grundlagen-leistungserstellung-2jg":{schritte:[{titel:"Factors & output",blocks:[{type:"begriff",term:"Factors of production",erklaerung:"What a company needs to produce goods and services: human labour + business assets."},{type:"tabelle",spalten:["Factor of production","Examples"],zeilen:[["Human labour","managerial work, operational work (= human capital)"],["Fixed assets","Buildings, machines"],["Current assets","Raw materials, merchandise"]]},{type:"kette",glieder:[{titel:"Input",wert:"Factors of production"},{titel:"combining",wert:"Production"},{titel:"Output",wert:"Physical goods / services"}]},{type:"merke",text:"There are often hybrid forms: physical good + service (e.g. new software + staff training)."}]},{titel:"The production process",blocks:[{type:"kette",glieder:[{titel:"Procurement market →",wert:"Procurement"},{titel:"Combination",wert:"Production"},{titel:"→ sales market",wert:"Sales"}]},{type:"text",text:"Management stands above this. Support comes from logistics, HR, financial and quality management, accounting & controlling."},{type:"begriff",term:"Division of labour within the company",erklaerung:"Tasks are divided among departments (functional areas) – the bigger the company, the more so."}]},{titel:"Goals: productivity, economic efficiency, profitability",blocks:[{type:"tabelle",spalten:["Goals of production"],zeilen:[["Optimal use of the factors of production"],["Customer satisfaction"],["Low costs"],["Sustainable and ethical production"]]},{type:"formel",name:"Productivity",zaehler:"output in quantities",nenner:"input in quantities",beispiel:"Machine productivity = 200 parts / 4 hrs = 50 parts per hour"},{type:"merke",text:"Productivity = QUANTITIES (units, kg, hours). Rises through new technologies or better-trained staff – but is not automatically economical."},{type:"formel",name:"Economic efficiency",zaehler:"output in value (revenue)",nenner:"input in value (costs)",beispiel:"€18,000 / €15,000 = 1.2"},{type:"tabelle",spalten:["Result","Meaning"],zeilen:[["> 1","Profit"],["= 1","covering costs"],["< 1","Loss"]]},{type:"formel",name:"Profitability",zaehler:"Profit",nenner:"Capital invested",faktor:"· 100",beispiel:"500,000 / 6,000,000 · 100 = 8.33%"},{type:"merke",text:"Profitability = the return on the capital invested. The higher, the more successful."}]},{titel:"Customer satisfaction",blocks:[{type:"text",text:"Customers come back if quality, delivery time, punctuality and flexibility are right."},{type:"formel",name:"Delivery quality in %",zaehler:"Orders without quality defects",nenner:"All orders delivered",faktor:"· 100"},{type:"formel",name:"Product quality in %",zaehler:"Goods without quality defects",nenner:"All goods produced",faktor:"· 100",beispiel:"127 / 130 · 100 = 97.69%"},{type:"formel",name:"Ø delivery time",zaehler:"Sum of delivery times of all orders",nenner:"Number of orders"},{type:"formel",name:"Punctuality in %",zaehler:"Orders delivered on time",nenner:"All orders delivered",faktor:"· 100"},{type:"formel",name:"Flexibility in %",zaehler:"Special requests fulfilled",nenner:"Special requests received",faktor:"· 100"},{type:"merke",text:"Delivery time = from placing the order to fulfilment, usually in working days. Flexibility costs: more stock, modern equipment, qualified staff."}]},{titel:"Costs of production",blocks:[{type:"tabelle",spalten:["Type of cost","Meaning"],zeilen:[["Production costs","for using the factors of production (material-, equipment- or labour-intensive)"],["Storage costs","warehouse + stocks (spoilage, shrinkage, tied-up capital) + warehouse administration"],["Transport costs","supplier → company, within the company, company → customer"],["Indirect costs (overheads)","cannot be assigned directly: administration, marketing and sales"]]}]},{titel:"Sustainability & ethics",blocks:[{type:"begriff",term:"Sustainability",erklaerung:"Using resources so that they can grow back, current needs are met and future generations can also meet their needs."},{type:"tabelle",spalten:["Dimension","Meaning"],zeilen:[["Social","Responsibility towards stakeholders (fair wages, equal opportunities)"],["Economic","Making profits, e.g. to invest in new equipment"],["Ecological","Saving resources, few emissions and little waste"]]},{type:"begriff",term:"Cradle to cradle",erklaerung:"“From cradle to cradle”: after the life cycle, raw materials go back completely into production (circular economy)."},{type:"begriff",term:"Business ethics",erklaerung:"Which moral values and rules of conduct a company stands for. Often set out in a code of conduct.",beispiel:"No bullying, no accepting gifts, own solar power, donations to clubs"}]}],zusammenfassung:[{titel:"Basics",punkte:["Factors of production: human labour + business assets (fixed, current assets)","Output: physical goods (consumer/capital goods) and services","Process: procurement → production → sales; support from logistics, HR, finance, quality, accounting"]},{titel:"Key figures",punkte:["Productivity = output in quantities / input in quantities","Economic efficiency = revenue / costs (> 1 profit, = 1 covering costs, < 1 loss)","Profitability = profit / capital invested · 100","Delivery quality, product quality, punctuality, flexibility each in % (good / total · 100)","Ø delivery time = sum of delivery times / number of orders"]},{titel:"Costs & sustainability",punkte:["Costs: production, storage, transport, indirect costs","Sustainability: social, economic, ecological · cradle to cradle","Business ethics: values and rules of conduct (code of conduct)"]}]},"kunde-im-mittelpunkt":{schritte:[{titel:"What is marketing?",blocks:[{type:"begriff",term:"Marketing",erklaerung:"A way of thinking: the CUSTOMER is at the centre of all the company's activities – to delight customers, meet the needs of target groups and create unique customer experiences."},{type:"ablauf",titel:"Customer journey – touchpoints",schritte:[{titel:"Before the purchase",text:"First contact: influencers, social media, advertising"},{titel:"During the purchase",text:"Shop, online shop, app"},{titel:"After the purchase",text:"Customer service, members' club, offers"}]},{type:"begriff",term:"Touchpoints",erklaerung:"All the points where the customer comes into contact with a company/product. Each should be a positive experience."},{type:"begriff",term:"Multi-channel approach",erklaerung:"Using several sales channels to reach customers (branch, online shop, app)."},{type:"merke",text:"Negative customer opinions spread especially fast on the internet (social media, review sites)."}]},{titel:"Goals of marketing",blocks:[{type:"text",text:"Most important goal: to be successful against the competition on the market."},{type:"kette",glieder:[{titel:"Customer satisfaction, awareness, image, brand loyalty",wert:"Market-psychological goals"},{titel:"are a prerequisite for",wert:"→"},{titel:"Sales volume, turnover, market share, growth",wert:"Market-economic goals"}]},{type:"merke",text:"Market-psychological goals = how the company is perceived (hard to measure). Market-economic goals = figures (easy to measure)."}]},{titel:"STP: segmenting, targeting, positioning",blocks:[{type:"ablauf",titel:"Targeted marketing (STP)",schritte:[{titel:"Segmenting – market segmentation",text:"Dividing the overall market into sub-markets"},{titel:"Targeting – choosing segments",text:"Choosing the target market"},{titel:"Positioning – market positioning",text:"Convincing customers with a meaningful benefit"}]},{type:"tabelle",spalten:["Segmentation criterion","Examples"],zeilen:[["Geographic","Countries, cities"],["Demographic","Age, income, marital status, gender"],["Psychographic","Lifestyle, interests, values"],["Behavioural","Brand loyalty, buying behaviour (frequency, motive)"]]},{type:"tabelle",spalten:["Market coverage","Meaning","Example shoes"],zeilen:[["Concentrated","targeting 1 or more segments specifically","only sneakers for men"],["Differentiated","all segments, each in a different way","sneakers for men, women, children"],["Undifferentiated","the whole market without distinction","one sneaker model for everyone"]]},{type:"begriff",term:"USP (unique selling proposition)",erklaerung:"Unique selling point that sets you apart from the competition – in product, service, staff, technology or price.",beispiel:"Apple (technology), Amazon (fast delivery), Penny (low price)"},{type:"begriff",term:"Positioning map",erklaerung:"Chart with 2 axes (e.g. price and prestige) that shows your own position compared with the competition: actual positioning vs. target positioning."}]},{titel:"Marketing instruments (4 Ps)",blocks:[{type:"tabelle",spalten:["Instrument","4 Ps","Example"],zeilen:[["Product and range policy","Product","Smartphone with update guarantee"],["Price and terms policy","Price","10% discount in the online shop"],["Distribution policy (sales)","Place","Retail + own online shop"],["Communication policy","Promotion","Posters, advertising on YouTube"]]},{type:"begriff",term:"Marketing mix",erklaerung:"Sensible, coordinated combination of the 4 instruments. Based on the results of market research."}]}],zusammenfassung:[{titel:"Marketing",punkte:["Marketing = customer at the centre: delight, meet needs, unique experiences","Customer journey: touchpoints before, during and after the purchase","Goals: market-psychological (image, awareness) → prerequisite for market-economic (turnover, market share)"]},{titel:"STP",punkte:["Segmentation by geographic, demographic, psychographic, behavioural criteria","Market coverage: concentrated · differentiated · undifferentiated","Positioning: USP = unique selling point; positioning map (actual/target)"]},{titel:"Instruments",punkte:["4 Ps: product, price, place, promotion → together = marketing mix"]}]},marktforschung:{schritte:[{titel:"Tasks of market research",blocks:[{type:"begriff",term:"Market research",erklaerung:"Systematically collecting and analysing important information about the market and market participants (target group, competition)."},{type:"text",text:"Main task: gaining information so that marketing decisions are based on facts instead of guesses. Information about:"},{type:"tabelle",spalten:["Area","Example"],zeilen:[["Customer satisfaction and loyalty","Are customers satisfied?"],["Market position","Market share, level of awareness"],["Market development","Market growth, trends"],["Customer segments","Who are the customers, how do you reach them?"],["Customer behaviour and needs","What do they buy and how?"],["Competitors","What is the competition doing?"]]}]},{titel:"Secondary vs. primary",blocks:[{type:"vergleich",links:{titel:"Secondary market research",punkte:["Analyses data that ALREADY EXISTS","Cheaper","e.g. customer file, competitors' brochures, Google Analytics"]},rechts:{titel:"Primary market research",punkte:["Collects NEW data, directly on the market","More expensive, but exactly suited","Survey, observation, experiment, panel"]}},{type:"vergleich",frage:"Sources of information for secondary market research:",links:{titel:"Internal",punkte:["Sales reps' reports","Customer statistics","Accounting","Sales statistics"]},rechts:{titel:"External",punkte:["Internet (most important source)","Official statistics","External databases","Newspapers, books","Other companies' annual reports"]}},{type:"begriff",term:"SEO & SEA",erklaerung:"SEO = search engine optimisation (making the website more visible). SEA = search engine advertising (ads for matching search terms)."}]},{titel:"Full and partial survey",blocks:[{type:"vergleich",links:{titel:"Full survey (census)",punkte:["ALL people in the group (= population) are surveyed","e.g. all 100 passengers on a test flight"]},rechts:{titel:"Partial survey",punkte:["Only a part (= sample) is surveyed","The sample must be representative","e.g. 400 out of 50,000 passengers"]}},{type:"begriff",term:"Representative",erklaerung:"The sample reflects the most important characteristics (age, gender …) of the whole group – then the result is almost the same as with a full survey."}]},{titel:"Methods of primary market research",blocks:[{type:"tabelle",spalten:["Method","Types"],zeilen:[["Survey","in person (individual/group), by phone, in writing, online"],["Observation","in person, with devices (video, eye tracking), online (click behaviour, social listening, geotracking)"],["Experiment","Product test, store test, market test (also A/B tests, VR)"],["Panel survey","surveying/observing the same people regularly → changes and trends"]]},{type:"tabelle",spalten:["Question type","Meaning"],zeilen:[["Open question","answer in your own words → new insights"],["Closed question","answers given → quantitative (countable) results"],["Rating-scale question","choose an answer on a scale (1–6, smileys)"]]},{type:"merke",text:"Questionnaire: ice-breaker question at the start, demographic data at the end, guarantee anonymity."},{type:"vergleich",frage:"Observation setting:",links:{titel:"Field observation",punkte:["Natural environment","e.g. customers in the refurbished supermarket"]},rechts:{titel:"Laboratory observation",punkte:["Controlled conditions","e.g. test persons in a room with new packaging"]}},{type:"tabelle",spalten:["Experiment","What is tested?"],zeilen:[["Product test","Test persons try the product → feedback"],["Store test","Selling the product for a while in selected shops"],["Market test","Product + marketing on a test market before the launch"]]}]}],zusammenfassung:[{titel:"Basics",punkte:["Market research = systematic collection and analysis of market information","Information on: customer satisfaction, market position, market development, customer segments, customer behaviour, competitors"]},{titel:"Methods",punkte:["Secondary = existing data (internal: statistics; external: internet, official statistics)","Primary = new data: survey, observation, experiment, panel survey","Full survey (everyone) ↔ partial survey (representative sample)","Question types: open, closed, rating scale","Observation: field (natural) ↔ laboratory (controlled); in person, with devices, online","Experiments: product test, store test, market test","Panel = the same group of people regularly → spotting trends"]}]},"instrumente-marketings":{schritte:[{titel:"Product: benefits & brands",blocks:[{type:"begriff",term:"Product and range policy (product)",erklaerung:"Decides which products are offered and what features, functions and quality they have. Product = also services, people, places, organisations."},{type:"kette",glieder:[{titel:"Main purpose",wert:"Core benefit"},{titel:"+ extras",wert:"Additional benefit"},{titel:"+ service",wert:"Additional service"}]},{type:"text",text:"Example iPhone: core benefit = making calls · additional benefit = camera, apps, design, image · additional service = guarantee, Apple Store service. Together they make up the customer benefit."},{type:"merke",text:"Standing out from the competition usually only works through additional benefits and services → USP."},{type:"begriff",term:"Brand",erklaerung:"Protected sign (word/number, image or combined) that sets a product apart from the competition.",beispiel:"Coca-Cola (word) · Apple's apple (image) · BMW (combined)"},{type:"tabelle",spalten:["Type of brand","Meaning","Example"],zeilen:[["Manufacturer's brand","developed by the manufacturer","Nivea, Red Bull"],["Retailer's own brand","own brand of a retailer","Balea, ja! Natürlich"],["Individual brand","each product has its own brand","Duplo, Nutella (Ferrero)"],["Family brand","one brand for a product group","Nivea, Labello (Beiersdorf)"],["Umbrella brand","all products under one brand","Procter & Gamble"]]}]},{titel:"Product life cycle & portfolio",blocks:[{type:"begriff",term:"Product life cycle",erklaerung:"Like living things, products have a limited lifespan (technical innovations, trends)."},{type:"ablauf",titel:"Phases",schritte:[{titel:"Introduction",text:"Product is new on the market, low turnover"},{titel:"Growth",text:"catches on, turnover rises"},{titel:"Maturity",text:"maximum turnover"},{titel:"Saturation",text:"market saturated, turnover falls"},{titel:"Decline",text:"product is taken off the market"}]},{type:"merke",text:"Relaunch = changing a product in maturity/saturation to extend the cycle. Planned obsolescence = lifespan deliberately shortened."},{type:"begriff",term:"Portfolio analysis (BCG matrix)",erklaerung:"Grid with 4 fields: market growth (high/low) × relative market share (low/high)."},{type:"tabelle",spalten:["Field","Market growth / market share","Strategy"],zeilen:[["Question marks","high / low","watch, decide whether to invest"],["Stars","high / high","promote strongly, invest"],["Cash cows","low / high","hold position, “milk”"],["Poor dogs","low / low","take off the market"]]},{type:"formel",name:"Relative market share",zaehler:"own absolute market share",nenner:"absolute market share of the biggest competitor"}]},{titel:"Instruments of product policy & range",blocks:[{type:"tabelle",spalten:["Instrument","Meaning","Example"],zeilen:[["Product innovation","new product (truly new or similar to a competitor's) → introduction phase","ChatGPT from OpenAI"],["Product differentiation","further similar products for new target groups (growth/maturity)","Activity Family, Junior, Party"],["Product variation (relaunch)","improving an existing product (maturity/saturation)","Coca-Cola changes its recipe"],["Product elimination","taking a product off the market (decline)","printed encyclopaedias"],["Diversification","new product groups in the range","bicycle shop now also sells ski equipment"]]},{type:"vergleich",links:{titel:"Range width",punkte:["number of product groups","e.g. Yamaha: motorbikes, boat engines, instruments"]},rechts:{titel:"Range depth",punkte:["number of variants within one group","e.g. Vöslauer Balance: many flavours"]}},{type:"merke",text:"Differentiation → more depth. Diversification → more width. Elimination → less width/depth. Variation → changes nothing."}]},{titel:"Price and terms policy (price)",blocks:[{type:"begriff",term:"Price policy",erklaerung:"All decisions used to set prices – covering costs AND in line with the market. Terms policy = discounts, payment and delivery terms, guarantee."},{type:"tabelle",spalten:["Influencing factor","Meaning"],zeilen:[["Company's costs","Lower price limit: cover at least all costs"],["Customer demand","Upper price limit: the most customers will pay"],["Competitors' prices","Positioning: lower, the same or higher"]]},{type:"tabelle",spalten:["Type of strategy","Variants"],zeilen:[["Price positioning","High price (premium) · market price (average) · low price (promotion)"],["Price introduction","Skimming (start high, then lower – PS5) · market penetration (start low, then raise – Netflix)"],["Tactical","Price differentiation (by place, time, target group) · compensatory pricing (drinks more expensive than food)"],["Psychological","Price thresholds (€4.99) · price anchors (RRP crossed out) · multipack prices"],["Digital","dynamic, segmented, personalised pricing · subscription models"]]},{type:"begriff",term:"Shrinkflation",erklaerung:"Hidden price increase: less content for the same price (chocolate 100 g → 80 g)."}]},{titel:"Distribution policy (place)",blocks:[{type:"begriff",term:"Distribution policy (sales policy)",erklaerung:"Decides which sales channels bring the product to the end customer – and how shipping, transport and storage work."},{type:"vergleich",links:{titel:"Direct sales channel",punkte:["Company sells itself","Sales reps","Own shop (branch)","Own online shop"]},rechts:{titel:"Indirect sales channel",punkte:["Via intermediaries","Wholesale/retail (also franchising)","Trade intermediaries (sales agent, commission agent)","Online marketplaces (Amazon, eBay)"]}},{type:"merke",text:"Sales channels are often combined: click-and-collect (order online, pick up in the shop)."}]},{titel:"Communication policy (promotion)",blocks:[{type:"begriff",term:"Communication policy",erklaerung:"All the ways a company communicates with market participants to reach target groups and convey a positive image."},{type:"tabelle",spalten:["Corporate identity (CI)","Meaning"],zeilen:[["Corporate design","uniform look: logo, colours, font"],["Corporate communication","uniform communication internally and externally, slogan"],["Corporate behaviour","behaviour of staff (formal/informal address, dealing with customers)"]]},{type:"ablauf",titel:"AIDAS formula (advertising)",schritte:[{titel:"Attention",text:"Attract attention"},{titel:"Interest",text:"Arouse interest"},{titel:"Desire",text:"Desire to buy"},{titel:"Action",text:"Purchase (call to action)"},{titel:"Satisfaction",text:"Satisfaction after the purchase"}]},{type:"tabelle",spalten:["Audience","Meaning"],zeilen:[["Mass advertising","to many people, wastage possible (TV, poster)"],["Target-group advertising","specific group, little wastage"],["Individual advertising","one person (personalised e-mail)"]]},{type:"vergleich",links:{titel:"Advertising material",punkte:["Form in which the message is designed","graphic, audiovisual, interactive, goods as advertising","e.g. TV ad"]},rechts:{titel:"Advertising medium",punkte:["Carries the message","print, outdoor, electronic, internet, influencers","e.g. television"]}},{type:"formel",name:"Cost per thousand (CPM)",zaehler:"Costs · 1,000",nenner:"Number of people reached",beispiel:"500 · 1,000 / 50,000 = €10 per 1,000 people"},{type:"ablauf",titel:"Advertising planning",schritte:[{titel:"Advertising goals"},{titel:"Advertising budget"},{titel:"Advertising object",text:"product or company"},{titel:"Advertising subject",text:"target group"},{titel:"Advertising message"},{titel:"Advertising material and media"},{titel:"Advertising period"},{titel:"Checking advertising success"}]},{type:"begriff",term:"Greenwashing",erklaerung:"Presenting yourself as environmentally friendly in advertising without enough real measures – damages the image if it comes out."},{type:"tabelle",spalten:["Other instruments","Meaning"],zeilen:[["Public relations (PR)","Informing stakeholders: awareness, image, trust"],["Sales promotion","Incentives for customers (vouchers), staff (bonuses), retailers (discounts)"],["Sponsorship","Support with money/goods in return for advertising → awareness, image transfer"]]}]},{titel:"The marketing concept",blocks:[{type:"ablauf",titel:"Steps of a marketing concept",schritte:[{titel:"Situation analysis",text:"Target group and competitor analysis"},{titel:"Marketing goals",text:"market-psychological and market-economic"},{titel:"Marketing strategy",text:"STP: segmenting, targeting, positioning"},{titel:"Marketing mix",text:"product, price, place, promotion"},{titel:"Implementing measures",text:"Advertising planning, campaigns, success checks"}]},{type:"merke",text:"A marketing concept is constantly optimised and adapted to market changes. All points must fit well together."}]}],zusammenfassung:[{titel:"Product",punkte:["Customer benefit = core benefit + additional benefit + additional service → USP","Brands: word/image/combined · manufacturer/retailer brand · individual/family/umbrella brand","Life cycle: introduction → growth → maturity → saturation → decline (relaunch)","BCG: question marks (watch), stars (invest), cash cows (milk), poor dogs (eliminate)","Innovation, differentiation, variation, elimination, diversification","Range width (product groups) ↔ range depth (variants)"]},{titel:"Price",punkte:["Influencing factors: costs (lower limit), demand (upper limit), competition","High/market/low price · skimming / market penetration","Price differentiation, compensatory pricing, price thresholds, price anchors, dynamic pricing"]},{titel:"Place",punkte:["Direct (sales reps, branch, online shop) ↔ indirect (trade, intermediaries, marketplaces)"]},{titel:"Promotion",punkte:["CI: corporate design, communication, behaviour","AIDAS · mass/target-group/individual advertising","Advertising material (design) ↔ advertising medium (carrier) · CPM = costs · 1,000 / reach","Advertising planning: goal, budget, object, subject, message, material/media, period, success check","PR, sales promotion, sponsorship · beware of greenwashing","Marketing concept: situation analysis → goals → strategy (STP) → marketing mix → implementation"]}]},"material-warenwirtschaft":{schritte:[{titel:"Tasks & goals",blocks:[{type:"begriff",term:"Materials and merchandise management",erklaerung:"Provides the goods a company needs for its production."},{type:"tabelle",spalten:["The goods must be provided …"],zeilen:[["in the required quality"],["in the right quantity"],["at the right time"],["at the right place"]]},{type:"merke",text:"While minimising costs (procurement, materials, storage) and meeting social and ecological criteria (e.g. buying regionally)."},{type:"vergleich",links:{titel:"Materials management",punkte:["mainly in manufacturing companies","Procurement of raw, auxiliary and operating materials"]},rechts:{titel:"Merchandise management",punkte:["mainly in retail companies","Procurement of merchandise for customers"]}}]},{titel:"Areas & conflicting goals",blocks:[{type:"kette",glieder:[{titel:"Procurement marketing",wert:"Procurement"},{titel:"Warehouse logistics",wert:"Storage"},{titel:"Transport logistics",wert:"Distribution"},{titel:"Waste logistics",wert:"Disposal"}]},{type:"begriff",term:"Supply chain",erklaerung:"All participants from the raw material to the sale of the finished product. Supply chain management optimises the processes along this chain."},{type:"begriff",term:"Logistics",erklaerung:"System that ensures the optimal supply of goods and information within a company and across companies."},{type:"begriff",term:"Conflicting goals",erklaerung:"The material goal (smooth production), economic goal (minimising costs) and social/ecological goals compete with each other.",beispiel:"Regional ingredients: good for the environment, but more expensive"}]}],zusammenfassung:[{titel:"Materials & merchandise management",punkte:["Task: provide the goods needed in the right quality, quantity, time and place","Minimise costs + social/ecological criteria","Materials management (production: raw, auxiliary, operating materials) ↔ merchandise management (retail: merchandise)","Areas: procurement, storage, distribution (transport), disposal = supply chain","Conflicting goals: material goal ↔ economic goal ↔ social/ecological goals"]}]},beschaffungsmarketing:{schritte:[{titel:"Overview",blocks:[{type:"begriff",term:"Procurement marketing (procurement logistics)",erklaerung:"Marketing on the BUYING SIDE: influencing suppliers and the procurement market to optimise purchasing."},{type:"ablauf",titel:"Procedure",schritte:[{titel:"Procurement market research",text:"finding suitable markets and suppliers"},{titel:"Procurement programme policy",text:"which goods in what quantity?"},{titel:"Procurement method policy",text:"by which principle do we buy?"},{titel:"Procurement terms policy",text:"on what terms?"},{titel:"Procurement communication policy",text:"good supplier relationships"},{titel:"Carrying out and checking procurement"}]}]},{titel:"Market research & programme",blocks:[{type:"vergleich",frage:"Procurement market research:",links:{titel:"Secondary research",punkte:["Analysing existing information","internal: supplier file, warehouse statistics","external: catalogues, websites"]},rechts:{titel:"Primary research",punkte:["Gathering new information","Enquiries to suppliers","Visiting trade fairs","Asking experts"]}},{type:"text",text:"Criteria for choosing suppliers: e.g. price, quality, reliability, sustainability."},{type:"begriff",term:"Procurement programme policy",erklaerung:"Decides which goods and services are procured in what quantity – depending on the company's own production programme or range."}]},{titel:"Procurement organisation & principles",blocks:[{type:"vergleich",links:{titel:"Centralised procurement (1 department)",punkte:["+ good terms through large quantities","+ good control","− more administration","− not very flexible"]},rechts:{titel:"Decentralised procurement",punkte:["Several departments (branches)","More flexible in emergencies","Goods on site more quickly"]}},{type:"tabelle",spalten:["Principle","How it works","+","−"],zeilen:[["Stockpiling","buying and storing large quantities","always available, quantity discounts","high storage costs, tied-up capital, spoilage"],["Just-in-time","delivery exactly when needed","hardly any storage costs, little tied-up capital","production stops if delivery is late"],["Individual procurement","only order when there is an order","short storage time, no spoilage","delays, smaller discounts"]]},{type:"merke",text:"There is NO ideal principle – usually all three are combined, depending on the goods."}]},{titel:"ABC and XYZ analysis",blocks:[{type:"begriff",term:"ABC analysis",erklaerung:"Divides goods into 3 classes according to their share of the total value or total quantity."},{type:"tabelle",spalten:["Class","Share of value","Share of quantity","Measures"],zeilen:[["A goods","high (approx. 70%)","low (approx. 10%)","most attention, exact cost analysis, low stock"],["B goods","medium (approx. 20%)","medium (approx. 20%)","depending on importance"],["C goods","low (approx. 10%)","high (approx. 70%)","order rarely in large quantities, higher stock"]]},{type:"ablauf",titel:"ABC analysis in 3 stages",schritte:[{titel:"Record the figures",text:"Annual requirement in € = quantity · price"},{titel:"Sort the figures",text:"in descending order of value, assign a rank"},{titel:"Evaluate the figures",text:"calculate % share, cumulate, divide into classes (e.g. A < 75%, B 75–90%, C > 90%)"}]},{type:"formel",name:"Percentage share",zaehler:"Annual requirement of the item",nenner:"Total annual requirement",faktor:"· 100"},{type:"begriff",term:"XYZ analysis",erklaerung:"Divides goods according to how regularly they are used."},{type:"tabelle",spalten:["Class","Consumption","Forecast"],zeilen:[["X goods","regular","easy to predict"],["Y goods","seasonal fluctuations","roughly predictable"],["Z goods","very irregular","hardly predictable"]]},{type:"merke",text:"Combining ABC + XYZ: e.g. AX → just-in-time · CX → stockpiling · AZ → individual procurement."}]},{titel:"Requirements & order quantity",blocks:[{type:"begriff",term:"Programme-based requirement planning",erklaerung:"The quantity results from the production programme (orders)."},{type:"tabelle",spalten:["Calculating net requirements"],zeilen:[["Material requirement per bill of materials · production quantity"],["= gross requirement (total requirement)"],["− stock"],["= net requirement (actually to be procured)"]]},{type:"begriff",term:"Stock-based requirement planning",erklaerung:"The stock level decides whether to order."},{type:"tabelle",spalten:["Method","When is an order placed?"],zeilen:[["Reorder point system","automatically as soon as the reorder level is reached"],["Fixed-interval system","at fixed review times it is checked whether to order"],["Optional system","fixed times – but earlier if the reorder level is undershot"]]},{type:"begriff",term:"Reorder level",erklaerung:"Average consumption · procurement time + safety stock",beispiel:"10 bottles/week · 2 weeks + 5 = 25 bottles"},{type:"begriff",term:"Optimal order quantity",erklaerung:"Quantity at which ordering + storage costs are lowest. Small quantities → high ordering costs; large quantities → high storage costs."},{type:"formel",name:"Optimal order quantity",zaehler:"√(200 · annual requirement · fixed ordering costs)",nenner:"√(price per unit · storage cost rate)",beispiel:"√(200 · 2500 · 20 / (100 · 16)) ≈ 80 units"},{type:"merke",text:"Storage cost rate = interest rate + storage cost rate. The formula does not work if consumption fluctuates strongly."}]},{titel:"Terms, communication & implementation",blocks:[{type:"begriff",term:"Procurement terms policy",erklaerung:"Actively influencing contract terms: price (discount, cash discount), payment and delivery terms, guarantee."},{type:"begriff",term:"Procurement communication policy",erklaerung:"Building relationships with suppliers and winning new ones – through a positive image as a buyer (procurement advertising, PR, supplier development)."},{type:"ablauf",titel:"Carrying out and checking procurement",schritte:[{titel:"Requirement report"},{titel:"Selecting possible suppliers"},{titel:"Making enquiries / obtaining offers"},{titel:"Comparing offers"},{titel:"Order"},{titel:"Delivery"},{titel:"Receiving and checking the goods"},{titel:"Checking the invoice and paying"}]},{type:"begriff",term:"E-procurement",erklaerung:"Electronic procurement (B2B online trade). Closed systems (2 partners exclusively), semi-open (a retailer's portal), open (marketplace, e.g. Amazon Business)."}]}],zusammenfassung:[{titel:"Procurement marketing",punkte:["Market research (primary/secondary) → programme → methods → terms → communication → implementation & control","Centralised (cheap, control) ↔ decentralised procurement (flexible)","Stockpiling · just-in-time · individual procurement"]},{titel:"Analyses",punkte:["ABC: by share of value (A high value/small quantity, C low value/large quantity)","ABC stages: record → sort → evaluate (cumulate, classes)","XYZ: by consumption (X regular, Y seasonal, Z irregular)"]},{titel:"Requirements",punkte:["Programme-based: bill of materials · quantity = gross − stock = net requirement","Stock-based: reorder point, fixed-interval, optional system","Reorder level = Ø consumption · procurement time + safety stock","Optimal order quantity = √(200 · annual requirement · ordering costs / (price · storage cost rate))","E-procurement: closed, semi-open, open"]}]},"lager-transport-entsorgung":{schritte:[{titel:"Functions of the warehouse",blocks:[{type:"tabelle",spalten:["Function","Meaning","Example"],zeilen:[["Transformation (maturing)","Goods mature/dry in the warehouse","Wood, whisky, cheese"],["Safety","Safety stock for late deliveries or higher demand","Reserve stock"],["Speculation","buying early because prices will rise","Spices in stock"],["Balancing (bridging)","balancing timing between purchasing, production, sales","Schnapps delivered once a year"],["Presentation of goods","The warehouse is also the sales area","IKEA"],["Disposal","Collecting leftovers and packaging","Old stock, packaging"]]}]},{titel:"Types of warehouse",blocks:[{type:"tabelle",spalten:["Construction","For …","Example"],zeilen:[["Open warehouse","goods that are not sensitive to weather or theft","Raw timber, sand"],["Semi-open warehouse","paved area with fence/roof","Wooden boards, machines"],["Closed warehouse","goods sensitive to weather or at risk of theft","Food, electronics"]]},{type:"vergleich",frage:"By location:",links:{titel:"Central warehouse",punkte:["+ lower storage & staff costs","+ high availability of goods","+ less tied-up capital","− longer transport routes","− less flexible"]},rechts:{titel:"Decentralised warehouse",punkte:["Goods spread over several warehouses","Range tailored to nearby customers","shorter routes to customers"]}},{type:"vergleich",frage:"By allocation of storage space:",links:{titel:"Fixed-location system",punkte:["Each item has a fixed place","Space needed for the largest order"]},rechts:{titel:"Free-location system (chaotic)",punkte:["Goods go wherever there is free space","+ optimal use of space, flexible","− needs IT, not for dangerous goods","e.g. Amazon"]}}]},{titel:"Warehouse key figures",blocks:[{type:"text",text:"Goal: minimise costs, maximise income and liquidity, avoid slow-moving stock. Stock depending on ABC: monitor A goods closely, low stock · C goods higher stock."},{type:"formel",name:"Ø stock",zaehler:"Opening stock + closing stock",nenner:"2",beispiel:"(20,000 + 25,000) / 2 = €22,500"},{type:"formel",name:"Stock turnover rate",zaehler:"Cost of goods sold",nenner:"Ø stock",beispiel:"50,000 / 22,500 = 2.22 times a year"},{type:"formel",name:"Stock turnover period",zaehler:"365",nenner:"Stock turnover rate",beispiel:"365 / 2.22 = 164 days"},{type:"formel",name:"Storage costs in %",zaehler:"Storage costs",nenner:"Ø stock",faktor:"· 100"},{type:"merke",text:"The turnover rate should be HIGH, the turnover period SHORT. Achieved through stock monitoring, maximum stock levels, a leaner range, just-in-time, promotions. Cost of goods sold = cost price · sales."}]},{titel:"Transport & disposal",blocks:[{type:"begriff",term:"Transport logistics",erklaerung:"Moves goods from the supplier to the company, within the company and from the company to the customer. Goal: minimise transport times and routes, maximise security of supply."},{type:"begriff",term:"Waste logistics",erklaerung:"Collecting, sorting, packing, storing and removing waste (leftovers, rejects, packaging, returns)."},{type:"ablauf",titel:"Waste hierarchy (most important first)",schritte:[{titel:"Waste prevention"},{titel:"Preparing for re-use"},{titel:"Recycling"},{titel:"Other recovery",text:"e.g. composting, energy"},{titel:"Disposal",text:"only if nothing else is possible"}]},{type:"merke",text:"Since 2025 there has been a deposit on single-use drinks packaging in Austria (25 cents)."}]}],zusammenfassung:[{titel:"Warehouse",punkte:["Functions: transformation, safety, speculation, balancing, presentation of goods, disposal","Construction: open, semi-open, closed","Location: central (cheap, efficient) ↔ decentralised (close to customers)","Storage space: fixed location ↔ free location (chaotic, IT)"]},{titel:"Key figures",punkte:["Ø stock = (opening + closing stock) / 2","Turnover rate = cost of goods sold / Ø stock (high = good)","Turnover period = 365 / turnover rate (short = good)"]},{titel:"Transport & disposal",punkte:["Transport: supplier → company → internal → customer","Waste hierarchy: prevent → re-use → recycle → recover → dispose"]}]},"supply-chain-management":{schritte:[{titel:"What is SCM?",blocks:[{type:"begriff",term:"Supply chain (value chain)",erklaerung:"All companies involved in making a product – from the raw material to the end consumer."},{type:"kette",glieder:[{titel:"1",wert:"Sub-supplier"},{titel:"2",wert:"Supplier"},{titel:"3",wert:"Manufacturer"},{titel:"4",wert:"Retail"},{titel:"5",wert:"End consumer"}]},{type:"begriff",term:"Supply chain management (SCM)",erklaerung:"Planning the optimal flow of materials and information at ALL stages of the supply chain – all links work together."},{type:"merke",text:"Goods, money, services and information flow along the supply chain. At the end comes the waste disposal company."}]},{titel:"Opportunities & risks",blocks:[{type:"vergleich",links:{titel:"Opportunities",punkte:["Higher customer satisfaction (punctuality, quality)","Less tied-up capital (lower stocks)","Demand easier to predict","Time saving (shorter lead time)","Synergies (e.g. joint marketing)"]},rechts:{titel:"Risks",punkte:["Internal knowledge becomes public","Damage to image through others' mistakes","Dependence (a failure hits the whole chain)","A lot of time required, complexity"]}},{type:"begriff",term:"Lead time",erklaerung:"The time needed to process an order or a process between companies."},{type:"merke",text:"EU Supply Chain Act (2024): EU companies may not work with suppliers that use child or forced labour."}]},{titel:"Measures for successful SCM",blocks:[{type:"begriff",term:"Resilient supply chain",erklaerung:"Able to withstand unforeseeable events (war, pandemic, economic crisis) – disruptions are cushioned."},{type:"tabelle",spalten:["Measure","Meaning"],zeilen:[["Supply chain software","APS systems help with planning and control"],["Multi-sourcing","several suppliers instead of one (e.g. Apple: China + India + Vietnam)"],["Optimise cooperation","common goals, clear contracts, transparent data exchange"],["Focus on customers","align everything with customer needs"],["Plan buffer stocks","cost money, but secure supply"]]},{type:"begriff",term:"Resilience-efficiency dilemma",erklaerung:"More security (buffers, several suppliers) costs more money and coordination – less efficient."}]}],zusammenfassung:[{titel:"Supply chain management",punkte:["Supply chain = all companies from raw material to end consumer","SCM = optimal flow of materials and information along the whole chain","Opportunities: customer satisfaction, less tied-up capital, shorter lead time, synergies","Risks: loss of knowledge, damage to image, dependence, complexity","Resilience through: SCM software (APS), multi-sourcing, cooperation, customer focus, buffer stocks","Resilience-efficiency dilemma: more security = more costs"]}]},logistik:{schritte:[{titel:"Logistics companies",blocks:[{type:"begriff",term:"Logistics",erklaerung:"Integrated planning, control, execution and monitoring of all flows of goods and information. Part of the supply chain."},{type:"tabelle",spalten:["Logistics company","Task","Example"],zeilen:[["Freight forwarder (transport organiser)","organises transport in its own name, hires carriers","LKW WALTER, DB Schenker"],["Carrier (transport company)","actually carries out the transport","Haulage company with lorries"],["Warehouse and transhipment company","collecting, storing, reloading, distributing","Port of Vienna, Cargo Center Graz"],["Delivery services","smaller shipments to the front door","Post, courier, express, parcel services"]]},{type:"vergleich",frage:"Contracts:",links:{titel:"Forwarding contract",punkte:["Client ↔ freight forwarder"]},rechts:{titel:"Contract of carriage",punkte:["Freight forwarder ↔ carrier"]}},{type:"tabelle",spalten:["","Freight forwarder","Carrier"],zeilen:[["Duties","Duty of care, liability for damage to property and financial loss","Duty to carry, duty of care, liability if at fault"],["Rights","Forwarding commission, lien, right to carry out the transport itself","Right to payment (freight), lien"]]}]},{titel:"Means of transport",blocks:[{type:"text",text:"Criteria for choosing: costs & speed, reliability, safety, environmental impact, capacity for bulk goods, suitability for certain goods, network."},{type:"tabelle",spalten:["Means of transport","Advantages","Disadvantages","Suitable for"],zeilen:[["Road (lorry)","flexible, door to door","pollutants, traffic jams, driving bans","Piece goods, just-in-time"],["Rail (train)","most environmentally friendly, safe, large capacity","tied to rails, reloading needed","Bulk goods, dangerous goods"],["Inland ship","cheap, environmentally friendly","slow, tied to waterways","Heavy, non-perishable goods"],["Ocean ship","largest capacity, cheap, overseas","slow, piracy","Containers, large shipments"],["Aircraft","fastest, dense network","most expensive, little capacity, noise","Light, perishable, valuable goods"]]},{type:"begriff",term:"Own-account transport",erklaerung:"A company transports its goods with its own vehicles and staff."},{type:"begriff",term:"Combined transport",erklaerung:"Goods in loading units are carried by at least 2 modes of transport without reloading."},{type:"vergleich",links:{titel:"Container transport",punkte:["The container is reloaded","Inland containers, overseas containers"]},rechts:{titel:"Piggyback transport",punkte:["Load-on/load-off: semi-trailer only","Rolling motorway (RoLa): whole lorry on the train","Roll-on/roll-off (RoRo): whole lorry on the ship"]}}]},{titel:"Transport documents",blocks:[{type:"vergleich",links:{titel:"Consignment notes",punkte:["Proof that the goods have been shipped","Road: CMR consignment note","Rail: CIM consignment note","Air: air waybill"]},rechts:{titel:"Documents of title",punkte:["Security: certifies the right to the goods","Ocean bill of lading","Inland waterway bill of lading","FIATA multimodal (FBL) – combined"]}},{type:"merke",text:"Consignment notes → road, rail, air. Documents of title → ship and combined transport. Whoever holds the document of title can dispose of the goods."},{type:"begriff",term:"Accompanying documents",erklaerung:"Accompany the freight: certificate of origin, movement certificate, licences, pro forma and commercial invoice, packing list."}]}],zusammenfassung:[{titel:"Logistics companies",punkte:["Freight forwarder organises (forwarding contract), carrier transports (contract of carriage)","Forwarder: commission, lien, right to transport itself · carrier: freight, lien","Warehouse/transhipment companies, delivery services (post, CEP)"]},{titel:"Transport",punkte:["Lorry flexible · rail environmentally friendly · inland ship cheap · ocean ship largest capacity · aircraft fast/expensive","Own-account transport = own vehicles","Combined transport: container transport · piggyback (LoLo, RoLa, RoRo)"]},{titel:"Documents",punkte:["Consignment notes: CMR (lorry), CIM (rail), air waybill (air)","Documents of title (security): ocean/inland waterway bill of lading, FBL"]}]},"der-handel":{schritte:[{titel:"Basics of trade",blocks:[{type:"begriff",term:"Trading company",erklaerung:"Buys products from manufacturers, puts them together into a range and sells them on – WITHOUT significantly processing them."},{type:"vergleich",frage:"By type of customer:",links:{titel:"Retail",punkte:["Sells to end consumers","e.g. Thalia, Lidl"]},rechts:{titel:"Wholesale",punkte:["Sells to other companies","e.g. Metro, Schachermayer"]}},{type:"vergleich",frage:"By economic area:",links:{titel:"Domestic trade",punkte:["Within one country"]},rechts:{titel:"Foreign trade",punkte:["Between different countries"]}},{type:"merke",text:"Trade is Austria's second-largest employer – about a quarter of all employees."}]},{titel:"Functions of trade",blocks:[{type:"tabelle",spalten:["Function","Meaning","Example"],zeilen:[["Bridging space","Bringing products from where they are made to where they are sold (transport)","Buying Coca-Cola anywhere in the world"],["Bridging time","Storage between production and sale","Christmas baubles bought in June, stored until October"],["Quantity balancing","buying large quantities, selling small ones (collecting and distributing)","Grain from many farmers → flour to bakeries"],["Quality balancing","creating a range that meets needs, checking quality","Collections with matching colours"]]}]},{titel:"Types of retail business",blocks:[{type:"text",text:"Differ in range, type of service, prices and sales area."},{type:"tabelle",spalten:["Stationary (fixed location)","Explanation"],zeilen:[["Specialist shop","one industry, wide choice, advice (perfumery)"],["Specialist superstore","large area, self-service, fairly cheap (MediaMarkt)"],["Supermarket","Food + everyday goods"],["Discounter","low prices, simple fittings (Lidl, Penny)"],["Shopping centre","many shops under one roof (SCS)"],["Convenience store","small, long opening hours, higher prices (petrol station shop)"],["Factory outlet centre","branded goods cheaper (Parndorf)"],["Pop-up store","temporarily in empty shops"]]},{type:"vergleich",links:{titel:"Mail-order trade (distance trade)",punkte:["Ordered from a distance, delivered to your home","Classic mail order (catalogue)","Teleshopping","E-commerce: online shop, online marketplace, m-commerce"]},rechts:{titel:"Mobile (semi-stationary) trade",punkte:["No fixed location","Street/market trade (weekly market)","Direct sales (sales reps, home parties)"]}}]},{titel:"Wholesale & cooperation",blocks:[{type:"tabelle",spalten:["Type of wholesale business","How it works"],zeilen:[["Delivery wholesale","customer orders (sample/catalogue), wholesaler delivers"],["Collection wholesale","customer collects; cash-and-carry = serve yourself, pay immediately (Metro)"],["Rack jobber","rents shelves in other shops (Tchibo in the supermarket)"],["Online marketplace (e-procurement)","online purchasing platform for companies"]]},{type:"begriff",term:"Cooperation",erklaerung:"Voluntary, contractual cooperation to stay competitive."},{type:"tabelle",spalten:["Form of cooperation","Meaning","Example"],zeilen:[["Retail cooperative","retailers run purchasing and logistics together","ADEG, Lagerhaus"],["Franchise business","independent franchisee uses the franchisor's concept","McDonald's"],["Voluntary chain","independent retailers, shared brand and tasks","SPAR"]]}]},{titel:"Success factors & trends",blocks:[{type:"tabelle",spalten:["Success factor","Meaning"],zeilen:[["Designing the range","right width and depth; manufacturers' and own brands"],["Suitable price policy","discounts, special offers"],["Appealing merchandising","overall presentation: shop architecture, colours, shelf placement, lighting, music, senses"],["Ideal location","rent, closeness to customers, competition, transport links"],["Staff","qualified and motivated, good advice"],["Customer loyalty","loyalty cards, discount campaigns, newsletters, customer clubs"],["Multi-channel solutions","several sales channels: shop, online shop, marketplaces, social media"]]},{type:"tabelle",spalten:["Trends in trade"],zeilen:[["New technologies (robots, payment systems like Amazon Go)"],["Smart omni-channel solutions"],["Sustainability and social responsibility"],["Personalisation"],["Regional products"]]}]}],zusammenfassung:[{titel:"Basics",punkte:["Trading company = buys and sells without significant processing","Retail (to consumers) ↔ wholesale (to companies) · domestic ↔ foreign trade","Functions: bridging space & time, quantity & quality balancing"]},{titel:"Types of business",punkte:["Stationary retail: specialist shop, specialist superstore, supermarket, discounter, shopping centre, convenience, outlet, pop-up","Mail order: catalogue, teleshopping, e-commerce (online shop, marketplace, m-commerce)","Mobile: market trade, direct sales","Wholesale: delivery, collection (cash-and-carry), rack jobber, online marketplace","Cooperation: retail cooperative, franchising, voluntary chain"]},{titel:"Success & trends",punkte:["Range, price, merchandising, location, staff, customer loyalty, multi-channel","Trends: technology, omni-channel, sustainability, personalisation, regional products"]}]},"businessplan-2jg":{schritte:[{titel:"Structure of the business plan",blocks:[{type:"begriff",term:"Business plan",erklaerung:"Presents the business idea and describes how it will be put into practice. A well-thought-out business plan greatly increases the chances of success."},{type:"ablauf",titel:"Components (approx. 20–30 pages)",schritte:[{titel:"Executive summary"},{titel:"Company"},{titel:"Product and/or service"},{titel:"Industry, market and competition"},{titel:"Marketing"},{titel:"Opportunities and risks"},{titel:"Financial planning"},{titel:"Implementation roadmap"}]},{type:"begriff",term:"Executive summary",erklaerung:"Short summary with the key statements and most important figures. It comes first but is written LAST. It should make readers curious."},{type:"merke",text:"Add: cover page, table of contents, list of sources. Detailed documents (CVs, quotes) go in the appendix."}]},{titel:"Company & location",blocks:[{type:"tabelle",spalten:["Company and founder profile","Content"],zeilen:[["Business idea and vision","Vision = a picture of how the company should develop in the long term"],["Key people","Founders, managers and their qualifications"],["Legal form and company name","weigh up advantages and disadvantages"],["Company location","think it through carefully – changing it later is expensive"]]},{type:"tabelle",spalten:["Location factors","Examples"],zeilen:[["Procurement-related","infrastructure, workers, closeness to suppliers, rents, quality of life"],["Production-related","legal regulations, taxes, subsidies, political stability"],["Sales-oriented","closeness to customers, competition, transport links, image of the location"]]},{type:"ablauf",titel:"Scoring method (points method)",schritte:[{titel:"Choose the important location factors"},{titel:"Weight the factors",text:"together 100%"},{titel:"Rate the locations",text:"e.g. 1 (very bad) to 5 (very good)"},{titel:"Points × weighting"},{titel:"Add up the weighted points"},{titel:"Highest result = best location"}]},{type:"tabelle",spalten:["Factor","Weighting","A: points → result","B: points → result"],zeilen:[["Closeness to customers","50%","2 → 1.0","5 → 2.5"],["Transport links","30%","5 → 1.5","4 → 1.2"],["Image of the location","20%","3 → 0.6","4 → 0.8"],["Total","100%","3.1","4.5 ✓"]]}]},{titel:"Goals & organisation",blocks:[{type:"tabelle",spalten:["Goal","Time frame","Example"],zeilen:[["Long-term (strategic)","> 5 years","Put values like sustainability into practice"],["Medium-term (tactical)","1–5 years","When will the company reach profit?"],["Short-term (operational)","< 1 year","Switch to recyclable packaging this quarter"]]},{type:"merke",text:"Write goals SMART: specific, measurable, attractive, realistic, time-bound. Profit zone = revenue > total costs."},{type:"begriff",term:"Organisational structure",erklaerung:"Which activities are needed – and who does them? Also list external partners (some tasks are outsourced)."}]},{titel:"Product, market & marketing",blocks:[{type:"tabelle",spalten:["Product/service","Content"],zeilen:[["Customer benefit and USP","advantages clearly from the customer's point of view"],["Stage of development","steps up to the first sale, market launch"],["Production of the product/service","What is made in-house, what is bought in? Machines, staff?"],["Intellectual property rights","protection against copycats"]]},{type:"vergleich",frage:"Intellectual property rights:",links:{titel:"Must be registered and paid for",punkte:["Patent (technical innovation)","Utility model (faster, weaker)","Trademark (logo, sign)","Design (appearance)","Indications of origin"]},rechts:{titel:"Free, not registered",punkte:["Copyright (creative works)","Trade secrets"]}},{type:"begriff",term:"Target group & market potential",erklaerung:"Target group = customers who benefit most, are willing to pay and are large enough. Market potential = the amount that could theoretically be sold."},{type:"formel",name:"Market potential",zaehler:"Number of possible buyers · annual purchase quantity",nenner:"1",beispiel:"1,000 people · 4 · 52 = 208,000 orders; × €10 = €2,080,000 in money terms"},{type:"vergleich",links:{titel:"Direct competition",punkte:["Same industry, same offer","ORF ↔ ProSieben, RTL"]},rechts:{titel:"Indirect competition",punkte:["Meets the same need in a different way","ORF ↔ streaming, social media"]}},{type:"merke",text:"Marketing: especially important in the start-up phase – cover all 4 Ps, as cheaply as possible."}]},{titel:"Opportunities, finance & implementation",blocks:[{type:"vergleich",frage:"External opportunities and risks:",links:{titel:"Opportunities",punkte:["Influencers create attention","Purchasing power of the target group rises","Little competition"]},rechts:{titel:"Risks",punkte:["Competitor with a better product","Purchasing power falls","Big customer becomes insolvent"]}},{type:"begriff",term:"Financial planning",erklaerung:"The heart of the business plan: how much capital is needed and how will it be raised (equity and debt)? The liquidity plan makes sure the company can always pay. At least for the first 3 years."},{type:"begriff",term:"Implementation roadmap (milestone plan)",erklaerung:"Lists steps and activities: who does what by when?"},{type:"ablauf",titel:"Creating the implementation roadmap",schritte:[{titel:"Put together work packages",text:"group related tasks"},{titel:"Set milestones",text:"checkable interim goals"},{titel:"Watch the critical path",text:"activities without time buffer"},{titel:"Monitoring",text:"target/actual comparison, take action if needed"}]},{type:"merke",text:"Support: business plan competitions (i2b, Jugend Innovativ), WKO start-up service, free software plan4you."}]}],zusammenfassung:[{titel:"Structure",punkte:["Executive summary · company · product · industry/market/competition · marketing · opportunities/risks · financial planning · implementation roadmap","Executive summary = short version, written last"]},{titel:"Company",punkte:["Profile: business idea & vision, people, legal form & company name, location","Location factors: procurement-related, production-related, sales-oriented","Scoring method: weight factors (100%) → rate → points × weight → add up → highest result","Goals: long-term (> 5 yrs), medium-term (1–5 yrs), short-term (< 1 yr), SMART"]},{titel:"Market & the rest",punkte:["Product: customer benefit/USP, stage of development, production, IP rights (patent, trademark … / copyright)","Market potential = possible buyers · annual purchase quantity (× price = in money)","Direct ↔ indirect competition","Financial planning: capital needed + financing + liquidity plan","Implementation roadmap: work packages, milestones, critical path, monitoring"]}]}},questions:{"unternehmer-firma-firmenbuch":[{question:"Which requirements must be met under the UGB for someone to count as an entrepreneur?",options:["A permanent organisation of independent economic activity, even without aiming for profit","A profit-oriented corporation entered in the company register with at least one managing director","A natural person whose main occupation is employment by someone else","A business with at least one employee and a minimum annual turnover of €35,000"],explanation:"Under the UGB, an entrepreneur is anyone who runs a permanent organisation of independent economic activity – even if it is not aimed at profit.",correctIndex:0},{question:"Loopy runs her Candy Store all alone, without partners. What type of entrepreneur is this?",options:["A legal person","A corporation","A cooperative","A natural person"],explanation:"Since Loopy, as an individual, is herself the bearer of rights and duties, she is a natural person.",correctIndex:3},{question:"Which statement about liberal professions (e.g. doctors, lawyers, architects) under the UGB is true?",options:["They only count as entrepreneurs if they have more than €700,000 turnover in two years","They are excluded from being entrepreneurs under the UGB and may not register at all","They are not automatically entrepreneurs under the UGB, but can register voluntarily","They must register in the company register just like corporations"],explanation:"Liberal professions such as doctors, lawyers or architects do not automatically fall under the UGB definition of entrepreneur, but can voluntarily register in the company register.",correctIndex:2},{question:`What is meant by a company's "Firma" under the UGB?`,options:["All the employees of a company, including the managing directors and apprentices","The name under which the entrepreneur does business and can sue or be sued","The total value of all assets shown in the company's balance sheet","The building where the registered office entered in the company register is located"],explanation:"Under the UGB, the Firma is the name under which an entrepreneur acts in business, concludes contracts and can sue or be sued.",correctIndex:1},{question:"What does the company name consist of?",options:["Core wording and legal form suffix","Company register number and registered office","Line of business and balance sheet date","Articles of association and specimen signature"],explanation:"The company name consists of the core wording (freely chosen name) and the legally required suffix that indicates the legal form.",correctIndex:0},{question:"What does the principle of exclusivity require when choosing a company name?",options:["The name may consist only of the owner's first name and surname, nothing else","The name must explicitly state the full business purpose of the company","The name must contain an invented name and no personal names","The name must clearly differ from names already registered in the same place"],explanation:"The principle of exclusivity requires a company name to clearly differ from names already registered in the same place, to avoid confusion.",correctIndex:3},{question:'Loopy wants to call her shop "Loopys Bio-Feinkost GmbH" (organic delicatessen), but only sells sweets without organic certification. Which principle of choosing a company name does she violate?',options:["Suitability as a name","Duty to register","Ban on misleading names","Exclusivity"],explanation:'The company name must not contain information that is misleading about the business – the word "Bio" (organic) would be deceptive here, as no organic products are sold.',correctIndex:2},{question:`What is a company name called that consists of the owner's name, e.g. "Thomas Radler e.U."?`,options:["Mixed name","Personal name","Descriptive name","Invented name"],explanation:"A personal name is derived from the name of one or more people working in the company.",correctIndex:1},{question:"Above which turnover must a sole proprietorship register in the company register?",options:["Over €1 million in one or over €700,000 in two consecutive financial years","Over €500,000 in one or over €100,000 in two consecutive financial years","From the first employee, regardless of turnover","Sole proprietorships never have to register; registration is always voluntary"],explanation:"Sole proprietorships must register in the company register once their turnover exceeds €1 million in one year or €700,000 in two consecutive financial years.",correctIndex:0},{question:"What does the company register consist of?",options:["Articles of association and statutes","Cash book and inventory book","Balance sheet and profit and loss account","Main register and collection of documents"],explanation:"The company register consists of the main register with the most important company data and the collection of documents with underlying documents such as the articles of association or balance sheet.",correctIndex:3}],"rechtsformen-unternehmen":[{question:"According to the textbook, which criterion is NOT one of the most important criteria for choosing the legal form?",options:["The founder's favourite colour","Liability for the company's debts","Raising capital (financing)","Management and control in the company"],explanation:"Criteria for choosing the legal form include raising capital, liability, management/control, type of bookkeeping and the tax burden – but not personal preferences.",correctIndex:0},{question:"Which statement about the sole proprietorship is true?",options:["The sole proprietor is only liable with the capital invested in the business","A sole proprietorship always needs a minimum capital of €10,000 in cash","A sole proprietorship must be founded by notarial deed and registered","The sole proprietor is liable without limit with all personal assets"],explanation:"Sole proprietors are fully, personally and unlimitedly liable with all their assets – in return, it can be founded without formalities and without minimum capital.",correctIndex:3},{question:"How many partners are needed at least to found a general partnership (OG)?",options:["At least 3 people","At least 5 people","At least 2 people","At least 1 person"],explanation:"The OG is founded by at least two people who share equal rights and duties in the company.",correctIndex:2},{question:"How are the partners of an OG liable for the company's debts?",options:["Only proportionally according to their capital contribution","Personally, without limit, directly and jointly and severally","Only with their contribution entered in the company register","Not at all, since the OG has its own legal personality and is liable alone"],explanation:"All partners of an OG are liable personally, without limit, directly and jointly and severally – creditors can therefore turn to any individual partner for the entire debt.",correctIndex:1},{question:"Marius is the general partner, Lisa the limited partner of a KG. Which statement about liability is true?",options:["Marius is liable without limit and personally, Lisa only up to her registered liability sum","Both are equally liable without limit and personally with their private assets","Lisa is liable without limit and personally, Marius only up to his liability sum","Neither is personally liable, as the KG is a corporation"],explanation:"In a KG at least one general partner is liable without limit and personally, while the limited partner is only liable up to the registered liability sum.",correctIndex:0},{question:"Which statement about the civil law partnership (GesbR) is true?",options:["Like an OG, it must be entered in the company register and trade under a company name","It can already be founded by a single person without a partnership agreement","It is a form of corporation with its own legal personality","It has no legal personality of its own and is not entered in the company register"],explanation:"The GesbR has no legal personality of its own, does not operate under its own company name and is not entered in the company register.",correctIndex:3},{question:"What characterises the silent partnership?",options:["Like a general partner, the silent partner is liable without limit with private assets","The silent partnership must be entered in the company register with all partners","The silent partner only contributes capital and does not appear to the outside world","The silent partner acts in the company's name and represents it towards customers and suppliers"],explanation:"The silent partnership is a purely internal partnership – the silent partner only participates financially, does not appear to the outside world and is not entered in the company register.",correctIndex:2},{question:"According to the textbook, how high is the minimum share capital for founding a GmbH?",options:["€1,000.00","€10,000.00","€35,000.00","€70,000.00"],explanation:"To found a GmbH, a minimum share capital of €10,000.00 must be raised.",correctIndex:1},{question:"Which bodies does a GmbH have?",options:["Management, general meeting and (above a certain size) supervisory board","Management board, general meeting of shareholders and supervisory board","Only a managing director, without a general meeting or supervisory board","General partner and limited partners"],explanation:"The GmbH is run by the management, the general meeting is the shareholders' highest body, and above a certain size a supervisory board is also required.",correctIndex:0},{question:"According to the textbook, how high must the share capital of a public limited company (AG) be at least, and what portion must be paid in cash immediately?",options:["At least €10,000.00, half of it in cash","At least €35,000.00, all in cash","At least €100,000.00 with no cash payment obligation","At least €70,000.00, a quarter of it in cash"],explanation:"The share capital of an AG must be at least €70,000.00, of which at least a quarter must be paid in cash.",correctIndex:3},{question:"Which bodies does a public limited company have?",options:["Only the management board as the company's sole body","Authorised officer, limited partner and general partner","Management board, supervisory board and general meeting","Management, general meeting and general partner"],explanation:"The AG is run by the management board, controlled by the supervisory board, and the shareholders decide on key matters at the general meeting.",correctIndex:2},{question:"What is special about the flexible company (FlexKapG)?",options:["Like in an OG, its partners are liable personally and without limit with private assets","It allows company value shares (UWA) for employees with preferential profit sharing","It does not need to be entered in the company register","Like an AG, it may sell its shares to any small investors on the Vienna Stock Exchange"],explanation:"The FlexKapG (also FlexCo) combines elements of the GmbH and AG and allows employees to participate in the company and preferentially in profits through company value shares (UWA).",correctIndex:1},{question:"Who is typically the general partner in a GmbH & Co KG?",options:["A GmbH, so that no natural person is liable without limit","Always a natural person who is liable without limit with private assets","The limited partner himself","A cooperative"],explanation:"In a GmbH & Co KG, the GmbH as a legal person takes on the role of the general partner with unlimited liability, so that no natural person is personally liable without limit.",correctIndex:0},{question:"According to the textbook, what is the main purpose of a cooperative?",options:["Maximum profit for external investors","Avoiding any register entry and disclosure","Limiting membership to a maximum of two people","Supporting the business or economy of its members"],explanation:"A cooperative is an association of people with an open number of members whose aim is to support the business or economy of its members through joint business operations.",correctIndex:3}],vollmachten:[{question:"What is meant by Prokura?",options:["The most extensive power of attorney a company can grant","A power of attorney that applies only to a single deal","A power of attorney that can only be granted orally","A power of attorney only for branch managers"],explanation:"Prokura is the most extensive power of attorney in a company and authorises almost all court and out-of-court transactions.",correctIndex:0},{question:"According to the textbook, who may grant Prokura?",options:["Every Prokurist can appoint further Prokuristen himself","Every employee with a commercial power of attorney","Only the company register court","Only the entrepreneur personally"],explanation:"Prokura may only be granted by the entrepreneur personally – expressly and by entry in the company register.",correctIndex:3},{question:"For what does a Prokurist additionally need express authority, even though he has Prokura?",options:["For signing invoices","For accepting payments from customers","For selling or mortgaging land","For buying goods in ordinary business"],explanation:"Selling and mortgaging land are among the transactions for which a Prokurist needs express additional authority despite having Prokura.",correctIndex:2},{question:"Loopy appoints two Prokuristen and stipulates that they may only act together. What type of Prokura is this?",options:["Mixed Prokura","Joint Prokura","Sole Prokura","Branch Prokura"],explanation:"With joint Prokura, several Prokuristen can only act and conclude contracts together, none of them alone.",correctIndex:1},{question:"How does a Prokurist sign correctly when acting on behalf of the company?",options:['With "ppa." before the signature','With "i. V." before the signature',"Without any addition, just with their own name",'With "i. A." before the signature'],explanation:'Prokuristen mark their signature with "ppa." (per procura), while holders of a commercial power of attorney use "i. V." or "i. A." depending on the power.',correctIndex:0},{question:"What does NOT end a Prokura?",options:["Revocation by the entrepreneur","Notice given by the Prokurist","The death or legal incapacity of the Prokurist","A short illness of the Prokurist"],explanation:"A Prokura ends by revocation, notice, death or legal incapacity of the Prokurist and by bankruptcy of the company – a short illness changes nothing.",correctIndex:3},{question:"How does the commercial power of attorney differ from Prokura?",options:["The commercial power of attorney is always more extensive than Prokura","The commercial power of attorney must always be entered in the company register","The commercial power of attorney is more limited in scope than Prokura","The commercial power of attorney may only be granted by the company register court"],explanation:"Unlike Prokura, the commercial power of attorney is a limited power and does not have to be entered in the company register.",correctIndex:2},{question:"Loopy allows her employee Karin to buy only sweets from suppliers, but not to do any other business. What type of commercial power of attorney is this?",options:["Prokura","Power of attorney for a type of deal","General commercial power of attorney","Special commercial power of attorney"],explanation:"A power of attorney for a type of deal only authorises a certain type of transaction – here buying sweets – while the general power covers all ordinary business and the special power only concerns a single specific deal.",correctIndex:1}],beschaeftigungsverhaeltnisse:[{question:'Which feature is typical of a "genuine" employment contract?',options:["Personal dependence and being bound by the employer's instructions","Complete freedom in choosing working hours and place of work","Obligation to deliver a specific piece of work or result","Registering yourself with the social insurance institution for the self-employed (SVS)"],explanation:`In a "genuine" employment contract, the employee owes their personal labour and is bound by the employer's instructions regarding working hours, place of work and work processes.`,correctIndex:0},{question:"According to the textbook, which statement about holiday jobs and compulsory internships of HAK students is true?",options:["They are always contracts for work, since a specific result is owed","No employment law provisions apply to them","They are freelance service contracts",'They generally count as "genuine" employment contracts'],explanation:'In both holiday jobs and compulsory internships, students work under a "genuine" employment contract and are subject to the corresponding legal provisions.',correctIndex:3},{question:"What applies to people in marginal employment?",options:["They must take out their own health and pension insurance with the SVS","Their employment automatically counts as a contract for work, without any employee rights","Their pay is under the marginal earnings threshold; they lack automatic health and pension cover","They are excluded from any entitlement to paid holiday and to continued pay during illness"],explanation:"People in marginal employment earn below the marginal earnings threshold; they are entitled to paid holiday and continued pay but – if they only work for one employer – are not automatically covered by health and pension insurance.",correctIndex:2},{question:'What characterises a freelance service contract compared with a "genuine" employment contract?',options:["Like a contractor, the freelancer always owes a finished piece of work","The freelancer is not bound by instructions on working hours and place of work","The freelancer is entitled to paid holiday just like a genuine employee","The client does not register the freelancer with the ÖGK; the freelancer does it alone"],explanation:"With a freelance service contract, the freelancer is not bound by instructions on working hours and place, but must still be registered with the ÖGK by the client and has no holiday entitlement.",correctIndex:1},{question:"What is the essential feature of a contract for work?",options:["The contractor owes a concrete result, not their labour itself","The contractor is integrated into the client's work organisation and bound by instructions","The contractor is entitled to paid holiday","The contractor is automatically insured with the ÖGK"],explanation:"With a contract for work, the contractor undertakes to deliver a result or work; pay is only due on completion, and they must insure themselves with the SVS.",correctIndex:0},{question:"For which of the following forms of employment is there NO entitlement to paid holiday?",options:['A "genuine" employment contract',"Marginal employment under a genuine employment contract",'A holiday job as a "genuine" employment contract',"A contract for work"],explanation:'Contractors are self-employed and owe a result – so they have no entitlement to paid holiday, unlike employees in a "genuine" employment relationship.',correctIndex:3},{question:`Loopy commissions a graphic designer once to design a new logo for "Loopy's Candy Store"; the designer decides her own working hours and place and owes the finished logo. Which type of contract is this most likely to be?`,options:["A freelance service contract","Marginal employment","A contract for work",'A "genuine" employment contract'],explanation:"Since the designer owes a concrete result (the finished logo), decides freely on time and place and uses her own tools, it is a contract for work.",correctIndex:2}],"kaufvertraege-aussenhandel":[{question:'What is meant by the term "foreign trade"?',options:["The umbrella term for import and export between countries","The exchange of goods only within one country","Trade between two branches of the same company within Austria","Storing imported goods in a customs warehouse before clearance"],explanation:"Foreign trade is the umbrella term for the cross-border exchange of goods and services, i.e. import and export.",correctIndex:0},{question:"Loopy sells a large delivery of her chocolates to a retailer in France. What is this called from the Austrian point of view?",options:["Import","Export","Transit trade","Re-export"],explanation:"Export means selling goods or services abroad.",correctIndex:1},{question:"Loopy buys cocoa beans from a supplier in Ecuador for her chocolate production. What is this called from the Austrian point of view?",options:["Export","Domestic trade","Import","Processing trade"],explanation:"Import means buying goods or services from abroad.",correctIndex:2},{question:"Why is foreign trade particularly important for Austria as a small, open economy?",options:["Because Austria has all the raw materials it needs in sufficient quantities","Because foreign trade means Austrian companies no longer pay any customs duties or taxes","Because Austrian companies are required by law to export a fixed share of their production","Because the small domestic market and lack of raw materials make export and import necessary for prosperity and jobs"],explanation:"Since the Austrian domestic market is small and important raw materials are lacking, export and import are central to employment, growth and prosperity; Austria has a high export ratio.",correctIndex:3},{question:"Loopy wants to export her chocolates to Japan for the first time, but finds it hard to find out whether there is any demand for her products there. Which risk of the initiation phase affects her here?",options:["Market risk","Transport risk","Exchange rate risk","Acceptance risk"],explanation:"Market risk means that in the initiation phase it is unclear whether there is enough demand in the target country or whether you can hold your own against the competition.",correctIndex:0},{question:"After the export order is fixed, sugar prices rise sharply, so that Loopy's chocolate production becomes more expensive than calculated. Which risk of the production phase applies here?",options:["Delivery risk","Production risk","Risk of non-payment","Market risk"],explanation:"Production risk (production phase) means that the actual production costs turn out higher than calculated or that production breaks down.",correctIndex:1},{question:"A container with Loopy's chocolates is damaged by a storm on its way to Canada by sea. What risk is this?",options:["Acceptance risk","Risk of non-payment","Transport risk","Market risk"],explanation:"Transport risk covers damage, loss or delay of the goods on the way to the buyer and belongs to the fulfilment phase of the export deal.",correctIndex:2},{question:"After proper delivery, the Canadian customer refuses to accept Loopy's chocolates because he supposedly cancelled the order. What risk is this?",options:["Exchange rate risk","Production risk","Transport risk","Acceptance risk"],explanation:"Acceptance risk means that the foreign buyer does not accept the goods that were properly delivered.",correctIndex:3},{question:"A foreign customer accepts Loopy's chocolates, but then gets into payment difficulties and does not pay the invoice. What is this risk called?",options:["Risk of non-payment (del credere risk)","Market risk (demand and competition risk)","Acceptance risk","Exchange rate risk (currency risk)"],explanation:"The risk of non-payment, also called credit or del credere risk, describes the danger that the buyer does not pay or does not pay in full despite delivery.",correctIndex:0},{question:"Loopy agrees a selling price in US dollars with a US importer. By the time of actual payment, the dollar rate falls, so Loopy receives less in euros than expected. What risk is this?",options:["Risk of non-payment","Exchange rate risk","Acceptance risk","Transport risk"],explanation:"Exchange rate risk arises when invoicing is in a foreign currency between the conclusion of the contract and payment and the rate changes to the disadvantage of one party.",correctIndex:1},{question:"Loopy orders cocoa beans from a new supplier in Ghana. She fears that the goods could be delivered late, in the wrong quantity or in poor quality. Which typical importer's risk does this describe?",options:["Market risk","Credit risk","Delivery risk","Exchange rate risk"],explanation:"Delivery risk is the importer's main risk: the goods ordered could be delivered late, in the wrong quantity or quality, or not at all.",correctIndex:2},{question:"Which statement about Incoterms is true?",options:["Incoterms are legally mandatory customs forms that must be completed for every export from the EU","Incoterms regulate the transfer of risk uniformly worldwide; in group D, however, the buyer bears costs and risk from the seller's works","Incoterms only apply to transport within the EU and replace the contract of sale between the parties there","Incoterms regulate the transfer of costs and risk uniformly worldwide; in group D the seller provides the goods at the destination"],explanation:"Incoterms (International Commercial Terms) are standardised delivery clauses that regulate the transfer of costs and risk and the parties' duties (groups E, F, C, D). In group D (e.g. DAP, DDP) the seller bears costs and risk up to the destination.",correctIndex:3},{question:"Which document in sea transport serves as accompanying document, transport contract AND document of title (proof of ownership) at the same time?",options:["Bill of lading","Commercial invoice","Certificate of origin","International consignment note (CMR)"],explanation:"The bill of lading is the key document in sea transport: it serves as the contract of carriage, confirmation of receipt of the goods and a document of title with which ownership of the goods can be transferred.",correctIndex:0},{question:"How does a documentary credit fundamentally differ from a documentary collection?",options:["With a documentary collection, the buyer's bank is liable for payment itself; with a documentary credit, it only passes on the documents","With a documentary credit, the buyer's bank is itself obliged to pay against compliant documents; with a collection, it only collects as a trustee","Both procedures are identical in content and differ only in the amount of the bank charges","The documentary credit is only used in domestic business, the documentary collection only in foreign trade"],explanation:"With a documentary credit, the importer's bank itself undertakes to pay as soon as the agreed documents are presented – this gives the exporter a high level of security. With a documentary collection, the bank only forwards the documents and collects the money, but is not itself liable for payment.",correctIndex:1}],"grundlagen-leistungserstellung-2jg":[{question:"According to the book, which two factors of production does a company need for operational production?",options:["Human labour and business assets","Natural resources and the owners' capital","Procurement and sales","Fixed assets and the marketing department"],explanation:"To produce its goods and services, a company needs the factors of production human labour and business assets, which are in turn divided into fixed and current assets.",correctIndex:0},{question:"What is a product called that includes both a physical good and an additional service (e.g. a machine with a maintenance contract)?",options:["Capital good","Hybrid form","Consumer good","Person-related service"],explanation:"In practice there are often hybrid forms in which physical goods are combined with additional services – a mixture of physical good and service.",correctIndex:1},{question:"According to the book, which three basic business functions are directly related to production?",options:["HR, finance, controlling","Logistics, quality management, accounting","Procurement, production, sales","Marketing, sales, customer service"],explanation:"The three basic business functions procurement, production and sales are directly related to production and are supported by logistics, HR, financial and quality management, among others.",correctIndex:2},{question:"In Loopy's Candy Store a packaging machine produces 4,000 sweets per hour. Which key figure is calculated here when the quantity produced is compared with the machine hours used?",options:["Profitability","Economic efficiency","Flexibility","Machine productivity"],explanation:"Productivity compares output in quantities with input in quantities; machine productivity is calculated as quantity produced divided by machine hours used.",correctIndex:3},{question:"The economic efficiency of Loopy's Candy Store is 0.9. What does this result mean?",options:["A loss is made","A profit is made","Costs are covered exactly","The figure says nothing about success"],explanation:"Economic efficiency compares output in value with input in value. If the value is less than 1, a loss is made.",correctIndex:0},{question:"Loopy's Candy Store makes a profit of €50,000 with equity of €500,000. How high is the return on equity?",options:["5%","10%","50%","1%"],explanation:"Profitability is calculated as profit divided by capital invested times 100: 50,000 / 500,000 × 100 = 10%.",correctIndex:1},{question:"According to the book, which four factors determine customer satisfaction?",options:["Price, advertising, brand, design","Productivity, economic efficiency, profitability, sustainability","Quality, delivery time, punctuality, flexibility","Procurement, production, sales, logistics"],explanation:"The factors of customer satisfaction are quality, delivery time, punctuality and flexibility.",correctIndex:2},{question:'What does the key figure "punctuality" show?',options:["How long customers have to wait for their order on average","How large the share of faultless goods is in the total quantity produced","How far a company can respond to special customer requests","How many of all deliveries reached the customers on schedule"],explanation:"Punctuality shows how many of all deliveries reached customers on time, and in B2B contracts it is often secured with a penalty for late delivery.",correctIndex:3},{question:"Which type of production cost do rent and energy costs for the warehouse belong to?",options:["Storage costs","Production costs","Transport costs","Indirect costs"],explanation:"Storage costs consist of the costs of the warehouse (e.g. rent, energy), stocks (spoilage, shrinkage, tied-up capital) and warehouse administration (wages, salaries).",correctIndex:0},{question:"Which three dimensions of sustainability are distinguished in the book?",options:["Regional, national and international sustainability","Social, economic and ecological sustainability","Financial, legal and organisational sustainability","Production, storage and transport sustainability"],explanation:"The three dimensions of sustainability are social (e.g. fair pay), economic (making profits for investment) and ecological sustainability (saving resources).",correctIndex:1},{question:'What is meant by a "code of conduct" in business ethics?',options:["A legal rule on export control that only applies to industrial companies in the EU","A key figure for assessing the economic efficiency of production and administration","A set of values and rules of conduct that everyone in the company must follow","A document for calculating profitability"],explanation:"The values and rules of conduct of business ethics can be set out, for example, in a code of conduct – a set of rules that everyone in the company has to follow.",correctIndex:2}],"kunde-im-mittelpunkt":[{question:"What is meant by the term marketing?",options:["Producing goods as cheaply as possible regardless of demand","Consistently aligning the company with customers' needs","Advertising products that have already been developed","A company's personnel administration"],explanation:"Marketing means consistently aligning all business activities with customers' needs.",correctIndex:1},{question:"Which phase does NOT belong to the customer journey?",options:["Awareness","Consideration","Production planning","Post-purchase phase"],explanation:"The customer journey typically includes the phases awareness, consideration, purchase and post-purchase – not production planning.",correctIndex:2},{question:"How do quantitative marketing goals differ from qualitative ones?",options:["Quantitative goals are measurable, qualitative ones concern e.g. image and satisfaction","Quantitative goals concern the image, qualitative ones sales and market share","Qualitative goals are always more important because they can be expressed exactly in figures","Quantitative goals only concern the HR department"],explanation:"Quantitative goals can be measured in figures, e.g. turnover or market share, while qualitative goals concern things like image or customer satisfaction.",correctIndex:0},{question:"What is meant by market segmentation?",options:["The merger of several companies into one market leader","Reducing the product range to the best-selling items","Dividing a market among rivals through price agreements","Dividing an overall market into groups with similar needs"],explanation:"In market segmentation, an overall market is divided into homogeneous buyer groups (segments) with similar needs.",correctIndex:3},{question:"Loopy's Candy Store wants to target only a small, particularly sweet-toothed group (e.g. fans of organic sweets). Which market coverage strategy is Loopy using?",options:["Undifferentiated marketing","Differentiated marketing","Concentrated marketing","Mass marketing"],explanation:"With concentrated marketing (niche marketing), a company focuses specifically on a single, special market segment.",correctIndex:2},{question:"What is it called when Loopy's Candy Store offers several different product lines for different customer groups at the same time (e.g. sugar-free, vegan, classic)?",options:["Concentrated marketing","Differentiated marketing","Undifferentiated marketing","Niche marketing"],explanation:"With differentiated marketing (multi-segment marketing), several market segments are each targeted with adapted marketing measures.",correctIndex:1},{question:"What is a USP?",options:["Universal service provider (basic utility supplier)","User support platform (customer service portal)","Sales tax percentage (VAT rate)","Unique selling proposition (unique feature)"],explanation:"USP stands for unique selling proposition – the unique promise with which a product stands out from the competition.",correctIndex:3},{question:'What are the classic instruments of the marketing mix (the "4 Ps")?',options:["Product, price, distribution, communication","Personnel planning, production, price, presentation","Press, politics, programme, portfolio","Price, personnel, process, product"],explanation:"The marketing mix covers product policy, price policy, distribution policy (place) and communication policy (promotion).",correctIndex:0},{question:"What is meant by customer orientation?",options:["Customers are ignored in decisions","Aligning all decisions solely with the lowest possible price","Customers themselves make all production decisions","Consistently aligning business decisions with customers' wishes"],explanation:"Customer orientation means consistently aligning all business decisions with customers' wishes and needs.",correctIndex:3},{question:"What is a positioning map used for?",options:["Calculating wage costs per department","Placing a product in a chart compared with competitors","Scheduling projects along a timeline","Showing the locations of your own and competitors' branches on a map"],explanation:"A positioning map shows in a chart how a product is perceived compared with competitors in terms of two features (e.g. price and quality).",correctIndex:1}],marktforschung:[{question:"What is meant by market research?",options:["Systematically obtaining, preparing and analysing market information","Developing and producing new sweets in your own lab","Systematically recording all business transactions in the books","Ongoing advertising to open up new sales markets"],explanation:"Market research is the systematic obtaining, preparing and analysing of information about the market.",correctIndex:0},{question:"What are the two basic types of market research?",options:["Internal and external research","National and international market research","Primary and secondary market research","Digital and analogue market research"],explanation:"A distinction is made between primary market research (field research) and secondary market research (desk research).",correctIndex:2},{question:"Loopy's Candy Store analyses existing statistics from the Chamber of Commerce and existing annual reports to identify trends in the sweets market. Which form of market research is Loopy using?",options:["Primary research (field research)","Experiment","Secondary market research","Field observation"],explanation:"Secondary market research (desk research) uses data that already exists and is available internally or externally.",correctIndex:2},{question:"Loopy has a new survey carried out among her regular customers about a new type of sweet. What form of market research is this?",options:["Secondary market research","Desk research","Secondary statistics","Primary market research"],explanation:"In primary market research (field research), new data is collected specifically for a particular purpose.",correctIndex:3},{question:"Which three methods are the classic instruments of primary market research?",options:["Survey, observation, experiment","Balance sheet, bookkeeping, stocktaking","Statistical analysis, industry reports, annual reports","Planning, control, organisation"],explanation:"The primary research methods are survey, observation and experiment.",correctIndex:0},{question:"An employee of Loopy's Candy Store discreetly watches how customers react in front of the sweets shelf in the real shop. What is this form of observation called?",options:["Laboratory observation","Experiment","Secondary research","Field observation"],explanation:"In field observation, behaviour is observed in the natural, real environment – unlike laboratory observation under artificial conditions.",correctIndex:3},{question:"Loopy tests a new, changed recipe in a selected test market under controlled conditions before the sweet is launched across Austria. Which method is Loopy using?",options:["Experiment (test marketing)","Survey (interview)","Secondary research (desk research)","Observation (field observation)"],explanation:"In an experiment (test marketing), products are tested under controlled conditions in a limited market before being launched everywhere.",correctIndex:0},{question:"What is the difference between an open question and a closed question in a questionnaire?",options:["With open questions you choose from given answers, with closed ones you answer freely","With open questions you answer freely, with closed ones you choose from given answers","Open questions are only asked orally, closed ones only in writing on the questionnaire","Closed questions are always longer"],explanation:"With open questions you can answer freely, with closed questions you choose from given answer options.",correctIndex:1},{question:"Which type of survey is suitable if Loopy wants to ask a larger number of customers about their satisfaction quickly and cheaply?",options:["Personal one-to-one interview on site","Telephone survey","Written online survey","Laboratory observation"],explanation:"A written online survey makes it possible to survey many people at the same time, quickly and cheaply.",correctIndex:2},{question:'What does the term "desk research" stand for?',options:["Primary market research through own surveys","Observing customers in the field, i.e. field research","Carrying out experiments","Analysing existing data, i.e. secondary market research"],explanation:'Desk research means analysing existing data "at the desk" – i.e. secondary market research.',correctIndex:3}],"instrumente-marketings":[{question:"Which of the four marketing instruments (marketing mix) does setting the selling price belong to?",options:["Price policy (price)","Product policy (product)","Distribution policy (place)","Communication policy (promotion)"],explanation:"The marketing mix consists of product, price, distribution and communication policy; pricing belongs to price policy.",correctIndex:0},{question:"Loopy pays particular attention to attractive packaging design for her sweets, which additionally delights her customers. What is this extra product benefit called?",options:["Core benefit","Additional benefit","Contribution margin","Range depth"],explanation:"The additional benefit adds to a product's core benefit and can be decisive for the purchase decision.",correctIndex:1},{question:"A supermarket sells sweets under its own label instead of the manufacturer's name. What is this type of brand called?",options:["Generic brand","Manufacturer's brand (branded article)","Retailer's own brand","Umbrella brand"],explanation:"Retailers' own brands are sold by the retailer itself under its own name, unlike manufacturers' brands.",correctIndex:2},{question:"In which order does a product go through the phases of the product life cycle?",options:["Growth – introduction – saturation – maturity – decline","Maturity – growth – introduction – decline – saturation","Saturation – decline – introduction – growth – maturity","Introduction – growth – maturity – saturation – decline"],explanation:"The product life cycle runs from introduction through growth and maturity to saturation and decline.",correctIndex:3},{question:"A product has both a high relative market share and high market growth. What is it called in portfolio analysis (market growth/market share matrix)?",options:["Star","Cash cow","Poor dog","Question mark"],explanation:'Products with a high market share and high market growth are called "stars" in the BCG matrix.',correctIndex:0},{question:'Which products are called "cash cows" in portfolio analysis?',options:["Products with a low market share and low market growth","Products with a high market share and low market growth","Products with a low market share and high market growth","Products with a high market share and high market growth"],explanation:"Cash cows have a high market share with only low market growth and deliver stable income.",correctIndex:1},{question:"Loopy removes a poorly selling sweet completely from her range. Which product policy instrument is she using?",options:["Product innovation","Product variation","Product elimination","Product differentiation"],explanation:"Product elimination means removing a product completely from the range.",correctIndex:2},{question:"Besides sweets, Loopy also offers chocolate and chewing gum, i.e. several different product lines. Which technical term describes this?",options:["Range depth","Product differentiation","Brand policy","Range width"],explanation:"Range width indicates the number of different product lines, range depth the number of variants within a product line.",correctIndex:3},{question:"Loopy calculates the selling price of a new sweet by adding a profit mark-up to her costs. Which pricing method is she using?",options:["Cost-based pricing","Demand-based pricing","Competition-based pricing","Psychological pricing"],explanation:"With cost-based pricing, the price is determined on the basis of costs plus a profit mark-up.",correctIndex:0},{question:"A company deliberately sets a low price when launching a new product in order to win many customers quickly. What is this price strategy called?",options:["High-price strategy (skimming)","Low-price strategy (penetration)","Prestige price strategy (premium pricing)","Mid-price strategy"],explanation:"The low-price strategy (penetration strategy) aims to win market share quickly through a low introductory price.",correctIndex:1},{question:"Loopy sells a bag of sweets for €2.99 instead of €3.00. Which psychological price strategy is she using?",options:["Prestige price","Dynamic pricing","Threshold price","Quantity discount"],explanation:"Threshold prices are just below a round amount and seem psychologically cheaper to customers.",correctIndex:2},{question:"An airline constantly changes its ticket prices in real time depending on demand and capacity. What is this digital price strategy called?",options:["Cost-based pricing","Skimming strategy","Personalised pricing (individual pricing)","Dynamic pricing"],explanation:"With dynamic pricing, prices are adjusted automatically and in real time to demand and capacity.",correctIndex:3},{question:"Which of the following measures belongs to terms policy?",options:["Granting a quantity discount for larger orders","Designing attractive packaging","Choosing the right advertising medium","Choosing wholesale as the sales channel"],explanation:"Discounts such as quantity discounts belong to terms policy, which regulates payment and delivery terms.",correctIndex:0},{question:"Loopy sells her sweets exclusively through her own online shop, without any intermediaries. Which sales channel is she using?",options:["Indirect sales channel","Direct sales channel","Selective sales channel","Exclusive sales channel"],explanation:"With a direct sales channel, the manufacturer sells its products directly to customers without intermediaries.",correctIndex:1},{question:"A luxury watch brand sells its products only through a very small number of strictly selected specialist retailers worldwide. What type of distribution is this?",options:["Intensive distribution","Selective distribution","Exclusive distribution","Digital distribution"],explanation:"With exclusive distribution, only a very limited number of carefully selected retailers are supplied.",correctIndex:2},{question:"Which of the following instruments is NOT one of the classic instruments of communication policy?",options:["Advertising","Public relations","Sales promotion","Range policy"],explanation:"Range policy is part of product policy, not communication policy.",correctIndex:3},{question:"Which three areas does a company's corporate identity typically include?",options:["Corporate design, corporate communication, corporate behaviour","Product policy, price policy, distribution policy","Corporate design, corporate governance, corporate finance","Segmentation, targeting, positioning"],explanation:"Corporate identity consists of corporate design, corporate communication and corporate behaviour.",correctIndex:0},{question:'Loopy designs an advert according to the AIDA formula. What does the "D" in AIDA stand for?',options:["Discount","Desire","Distribution","Decision"],explanation:"AIDA stands for attention, interest, desire and action.",correctIndex:1},{question:"A company runs a TV ad that addresses a large, undifferentiated target group with the same message. What form of advertising is this?",options:["Single advertising","Individual advertising","Mass advertising","Below-the-line advertising"],explanation:"Mass advertising addresses a broad, undifferentiated audience with a uniform message.",correctIndex:2},{question:"Loopy hands out free samples of sweets in her shop to encourage customers to buy. Which communication instrument is she using?",options:["Public relations","Sponsorship","Corporate identity","Sales promotion"],explanation:"Product samples are a typical sales promotion measure to encourage customers to buy in the short term.",correctIndex:3},{question:"What is meant by sponsorship as an instrument of communication policy?",options:["Financial or material support for people or organisations in return for advertising","Giving free product samples to customers to encourage them to buy","Financial support for clubs out of pure generosity, with nothing in return","Setting a product's selling price"],explanation:"With sponsorship, a company supports people or organisations financially or materially in return for an agreed advertising service.",correctIndex:0},{question:"What is the central goal of a company's public relations?",options:["Increasing sales in the short term through discount campaigns","Building a positive image and trust among the public","Winning new customers quickly through paid advertising","Opening up new sales channels"],explanation:"Public relations aims to build trust and a positive image among the public in the long term.",correctIndex:1}],"material-warenwirtschaft":[{question:"What is the task of materials and merchandise management?",options:["Only organising the sale of the finished products","Providing the goods a company needs for its production","Managing the wages and salaries of all production staff","Planning the advertising and pricing for Loopy's Candy Store"],explanation:"The task of materials and merchandise management is to provide the goods a company needs for its production.",correctIndex:1},{question:"For production in Loopy's Candy Store to run smoothly, the goods needed must be provided in the right quality, at the right time, at the right place and …",options:["at the cheapest price on the world market","provided in the right quantity","from a single supplier only","imported exclusively from abroad"],explanation:"The goods needed must be provided in the right quality, in the right quantity, at the right time and at the right place.",correctIndex:1},{question:"Which term is mainly used in retail companies such as Loopy's Candy Store when it comes to procuring merchandise for customers?",options:["Materials management","Manufacturing management","Merchandise management","Financial management"],explanation:"The term merchandise management is mainly used in retail companies (procuring merchandise for customers), while materials management is mainly used in manufacturing companies (procuring raw, auxiliary and operating materials).",correctIndex:2},{question:"Into which four areas are the tasks of materials and merchandise management divided?",options:["Procurement, storage, distribution and disposal","Production, marketing, sales and human resources","Purchasing, sales, accounting and controlling","Planning, organising, leading and controlling"],explanation:"The areas of materials and merchandise management are procurement, storage, distribution and disposal.",correctIndex:0},{question:"What is meant by supply chain management in the overview of materials and merchandise management?",options:["Managing customer complaints","Designing the sales shelves and shop windows in the sweet shop","Important decisions along the entire supply chain","Calculating employees' salaries"],explanation:"Supply chain management covers important decisions along the entire supply chain, as can be seen, for example, with the food retailer Hofer, which sources a large part of its range from regional producers to avoid long transport routes.",correctIndex:2}],beschaffungsmarketing:[{question:"According to the textbook, which procurement activity forms the basis for the targeted use of the other procurement instruments?",options:["Procurement communication policy","Carrying out procurement","Procurement market research","Procurement terms policy"],explanation:"It starts with searching for suitable suppliers as part of procurement market research, before the actual purchasing decisions are made using the procurement instruments.",correctIndex:2},{question:"According to the textbook, which four areas do the procurement instruments include?",options:["Programme policy, terms policy, production policy, communication policy","Market research, advertising policy, distribution policy, service policy","Range policy, price policy, communication policy, sales policy","Programme policy, method policy, terms policy, communication policy"],explanation:"The procurement instruments include procurement programme policy, procurement method policy, procurement terms policy and procurement communication policy.",correctIndex:3},{question:"Loopy visits a trade fair to meet new cocoa suppliers for her Candy Store. What type of procurement market research is this?",options:["Primary research, since new information is obtained directly","Secondary research, since existing documents are analysed","Neither secondary nor primary research, but procurement programme policy","Procurement communication policy, since there is communication with suppliers"],explanation:"Visiting events or trade fairs is primary research, in which new information is obtained directly – unlike secondary research, which analyses existing documents.",correctIndex:0},{question:"According to the textbook, which of the following sources is part of secondary research in procurement market research?",options:["Personal interviews with industry experts","Internal supplier files and warehouse statistics","Visiting a trade fair to get to know new suppliers","A direct enquiry to a new supplier"],explanation:"Secondary research means analysing information that already exists, e.g. internal documents such as supplier files or warehouse statistics.",correctIndex:1},{question:"What is decided in procurement programme policy?",options:["At what time and from which supplier goods are procured","At what prices and payment terms negotiations with suppliers take place","How relationships with suppliers are maintained through communication","Which goods and services are to be procured in what quantity"],explanation:"Procurement programme policy decides which goods (physical goods and services) are to be procured in what quantity – in line with the company's own production programme or range.",correctIndex:3},{question:"In the first step of an ABC analysis, how is an item's annual requirement in value calculated?",options:["Annual requirement in units divided by price per unit","Number of suppliers multiplied by stock","Annual requirement in units multiplied by price per unit","Average stock multiplied by the number of orders per year"],explanation:"The annual requirement in value is the annual requirement in units multiplied by the price per unit.",correctIndex:2},{question:"According to the textbook, how are A, B and C goods usually separated in an ABC analysis based on the cumulative share of value?",options:["A goods up to 75%, B goods 75–90%, C goods over 90%","A goods up to 50%, B goods 50–80%, C goods over 80%","A goods up to 90%, B goods 90–95%, C goods over 95%","A goods up to 30%, B goods 30–60%, C goods over 60%"],explanation:"The limits are often set at a cumulative share of value of 75% (A goods) and 90% (B goods), although the exact limits differ from company to company.",correctIndex:0},{question:"Who is the Lorenz curve used in the ABC analysis named after?",options:["Konrad Lorenz, the Austrian behavioural scientist","The US statistician and economist Max Otto Lorenz","The founder of a large German logistics group","A German auditing and accounting firm"],explanation:"The Lorenz curve goes back to Max Otto Lorenz, an American statistician and economist.",correctIndex:1},{question:"According to the textbook, which procurement measure is typical for A goods?",options:["Hardly any procurement market analyses and high stock","Ordering large quantities rarely to reduce ordering costs","Doing without supplier analyses completely in favour of regular suppliers","Detailed procurement market analyses and low stock"],explanation:"A goods are the most important goods and need the most procurement attention: detailed market analyses and low stock to keep tied-up capital low.",correctIndex:3},{question:"According to the textbook, how does a company typically deal with C goods?",options:["Elaborate procurement market analyses are carried out for every item","Work is done exclusively just-in-time and without stock","Orders are rare but large, to keep ordering costs low","New suppliers are constantly searched for and prices compared"],explanation:"For C goods hardly any procurement market analyses are carried out; since they are of little importance, orders are placed rarely but in larger quantities to keep ordering costs low.",correctIndex:2},{question:"How is the reorder level calculated?",options:["Safety stock divided by procurement time","Average consumption times procurement time plus safety stock","Annual requirement divided by the number of orders","Average consumption times procurement time minus safety stock"],explanation:"Reorder level = average consumption × procurement time + safety stock.",correctIndex:1},{question:"How does the reorder point system work in stock-based requirement planning?",options:["When the reorder level is reached, a fixed quantity is ordered automatically","Stock is checked at fixed intervals and then a decision is made about ordering","Orders are only placed once a year on a fixed date","Orders are only placed for customer orders, without stock"],explanation:"In the reorder point system, the order quantity and reorder level are fixed. When the reorder level is reached, an order is triggered automatically.",correctIndex:0},{question:"How does the fixed-interval system differ from the reorder point system?",options:["In the fixed-interval system there is no review interval, only a reorder level","The fixed-interval system is only used for A goods with a high share of value","In the fixed-interval system there is no reorder level and the same quantity is always ordered","In the fixed-interval system, it is checked at set intervals whether and how much to order"],explanation:"In the fixed-interval system, a review interval and a reorder level are set; at each review a decision is made whether and how much to order – especially useful when demand is irregular.",correctIndex:3},{question:"What is meant by the optional system of requirement planning?",options:["A system that only reviews at fixed intervals and defines no reorder level","A system used only for C goods with a low share of value","A system that reviews at intervals and also orders when the reorder level is reached","A system in which every single order is negotiated individually with the supplier"],explanation:"The optional system combines both methods: stock is checked at certain intervals, and an order is also placed whenever the reorder level is reached.",correctIndex:2},{question:"What characterises a closed system (closed shop) in e-procurement?",options:["Two companies are exclusively connected via their IT systems","A large retailer offers its products to several customers via a portal","An independent marketplace provides an open procurement platform for many suppliers","Procurement is done only by phone without IT support"],explanation:"In closed systems, two companies are connected exclusively. In the semi-open system a large retailer offers a portal to several customers; in the open system (catalogue system) an independent procurement platform is available.",correctIndex:0},{question:"What is the procurement principle called in which delivery takes place as directly as possible before production?",options:["Stockpiling","Just-in-time procurement","Individual procurement","Procurement programme policy"],explanation:"When the aim is for delivery to take place directly before production, it is called just-in-time procurement – unlike stockpiling (larger quantities in stock) or individual procurement (only when there is a specific customer order).",correctIndex:1}],"lager-transport-entsorgung":[{question:"Which warehouse function applies when Loopy buys large quantities of cocoa because she expects prices to rise?",options:["Speculation function","Safety function","Transformation function","Presentation function"],explanation:"With the speculation function, goods are bought early when prices are expected to rise in the future.",correctIndex:0},{question:"Which warehouse function describes wood, tobacco, whisky or cheese maturing during storage?",options:["Safety function","Transformation (maturing) function","Balancing or bridging function","Disposal function"],explanation:"The transformation function (maturing function) describes that certain goods such as wood, tobacco, whisky or cheese mature or change during storage.",correctIndex:1},{question:"In which type of warehouse are goods that are sensitive to weather and at risk of theft, such as food or electrical goods, typically stored?",options:["Open warehouse","Closed warehouse","Semi-open warehouse","Free-location warehouse"],explanation:"In a closed warehouse, goods that are sensitive to weather and at risk of theft are stored in a building, e.g. food or electrical goods.",correctIndex:1},{question:"According to the textbook example of Spar, what advantage does a central warehouse have over several decentralised warehouses?",options:["Shorter transport routes to customers","Greater adaptability in case of regional failures and supply shortages","Higher minimum stocks, which increases tied-up capital","Lower storage and staff costs, since only one warehouse is needed"],explanation:"A central warehouse offers lower storage and staff costs and more efficient organisation, among other things, but has the disadvantage of longer transport routes to the branches.",correctIndex:3},{question:"How does the free-location system (chaotic warehouse) work, as described in the textbook using the example of Amazon?",options:["Each item has a fixed, prescribed storage place that never changes","Each item is stored wherever a space is currently free","Goods are stored only in alphabetical order of their item names","Only goods from the same product group may be stored together"],explanation:"In the free-location system, goods are stored wherever there is free space; storage places are freely interchangeable, which requires a computer-aided warehouse management system.",correctIndex:1},{question:"How is the stock turnover rate calculated?",options:["Cost of goods sold divided by average stock","Average stock divided by cost of goods sold","365 divided by the stock turnover period","Stock on 1 January divided by stock on 31 December"],explanation:"Stock turnover rate = cost of goods sold / average stock. It shows how often an item was sold and replaced on average within a year.",correctIndex:0},{question:"According to the textbook, what goal does transport logistics pursue towards customers?",options:["Minimising the speed and security of supply","Maximising the speed and security of supply","Maximising transport and delivery times","Minimising the number of suppliers and transport partners"],explanation:"The goals of transport logistics include minimising transport and delivery times and maximising the speed and security of supply towards customers.",correctIndex:1},{question:"What was introduced in Austria on 1 January 2025 in waste logistics for single-use drinks packaging?",options:["A ban on PET bottles and aluminium cans","A compulsory 100% reusable quota for all drinks sold in shops","A 25-cent levy per bottle or can that is not refunded","A 25-cent deposit per bottle or can, refunded on return"],explanation:"Since 1 January 2025 there has been a deposit system in Austria: anyone buying drinks in PET bottles or aluminium cans pays a 25-cent deposit, which is refunded when the empties are returned.",correctIndex:3}],"supply-chain-management":[{question:"According to the textbook, what is meant by the supply chain?",options:["Only the transport companies that carry goods between suppliers and end consumers","All companies involved in a product, from the raw material to the end consumer","Only the purchasing and marketing departments of a single company","A company's internal accounting"],explanation:"The supply chain (value chain) includes all companies involved in making a product – from extracting raw materials to the end consumer.",correctIndex:1},{question:"What is supply chain management (SCM)?",options:["Planning the optimal flow of materials and information at all stages of the supply chain","The sole responsibility of a single company for its own production, stock and transport","Checking employee satisfaction at all stages of the supply chain","Only choosing the cheapest raw material supplier"],explanation:"Planning the optimal flow of materials and information at all stages of the supply chain is called supply chain management (SCM).",correctIndex:0},{question:"According to the textbook, what opportunity does effective supply chain management offer companies?",options:["Greater dependence on individual suppliers and transport routes","More time required due to more complexity","Less tied-up capital through lower stocks","A higher risk of damage to the image"],explanation:"Opportunities include higher customer satisfaction, less tied-up capital through lower stocks and a shorter lead time.",correctIndex:2},{question:"Which risk of supply chain management does the textbook example of the toy manufacturer Mattel show?",options:["Too much stock due to working with too many suppliers","Too little tied-up capital due to too low stocks","Too small a range of toys for older children","Damage to image due to a sub-supplier's lead paint"],explanation:"At Mattel, lead paint from a sub-supplier was found in a toy produced in China – an example of how mistakes along the supply chain can damage a company's image.",correctIndex:3},{question:'What is meant by a "resilient" supply chain?',options:["A supply chain with as few suppliers as possible to save costs","A supply chain that can withstand unforeseeable crises","A supply chain that relies exclusively on just-in-time without stock","A supply chain without any buffer stocks"],explanation:"Resilient supply chains can withstand unforeseeable events (e.g. war, pandemic, economic crisis), so that disruptions can be cushioned or overcome.",correctIndex:1},{question:"According to the textbook example, which measure for successful SCM is Apple implementing by moving part of iPhone production from China to India?",options:["Optimising cooperation with the existing main supplier","Planning higher buffer stocks in warehouses","Focusing more on customers in India","Relying on several suppliers (multi-sourcing)"],explanation:"Through multi-sourcing – such as partly moving iPhone production from China to India – Apple makes its supply chain more resilient to disruptions at a single location.",correctIndex:3}],logistik:[{question:"According to the textbook, what does the term logistics cover?",options:["Only the road transport of goods between supplier and customer","Only a company's warehousing and order picking","The planning, control and monitoring of all payment flows and cash flows in a company","The planning, control, execution and monitoring of all flows of goods and information"],explanation:"Logistics covers the integrated planning, control, execution and monitoring of all flows of goods and information. It is part of the supply chain.",correctIndex:3},{question:"According to the textbook, which four types of logistics companies are distinguished?",options:["Freight forwarder, carrier, warehouse and transhipment companies, delivery service","Freight forwarder, manufacturer, wholesale and retail businesses, delivery service","Road, rail, water and air transport","Purchasing, production, sales, marketing"],explanation:"Logistics companies include freight forwarders (transport organisers), carriers (transport companies), warehouse and transhipment companies and delivery services.",correctIndex:0},{question:"According to the textbook, what does a freight forwarder do?",options:["It always carries out the transport itself with its own lorries and drivers","It organises transport in its own name and hires carriers to do it","It only sells transport insurance to shippers","It is only responsible for customs clearance at the EU's external borders"],explanation:"Freight forwarders organise transport and all related services in their own name; they hire carriers (transport companies) to actually carry out the transport.",correctIndex:1},{question:"How does the carrier differ from the freight forwarder?",options:["The carrier only plans the route without transporting anything itself","The carrier is always identical to the commissioning freight forwarder","The carrier itself carries out the actual transport for other companies","The carrier is only responsible for customs formalities and transport insurance"],explanation:"Carriers carry out the actual transport by road, rail, pipeline, ship and air for other companies, while the freight forwarder organises the transport.",correctIndex:2},{question:"Which right allows the freight forwarder to carry out a transport itself, taking on the rights and duties of a carrier?",options:["Forwarder's lien","Right to a forwarding commission","Duty of care","Right to carry out the transport itself"],explanation:"Through the right to carry out the transport itself, the freight forwarder can also organise and carry out transport itself, taking on the rights and duties of a carrier.",correctIndex:3},{question:"According to the textbook overview, which disadvantage is attributed to road freight transport?",options:["Delivery delays due to traffic jams and accidents","Low loading capacity","Being tied to a fixed rail network","High risk of damage due to piracy on the high seas"],explanation:"Disadvantages of road freight transport include high pollution, Sunday and public holiday driving bans and delivery delays due to traffic jams and accidents.",correctIndex:0},{question:"How does the carrier's area of responsibility differ from the freight forwarder's?",options:["It organises transport in its own name and hires other companies","It carries out the actual transport, e.g. by lorry, rail or ship","It is only responsible for customs formalities at borders","It only handles warehousing, order picking and packaging"],explanation:"The carrier is responsible for the actual transport by road, rail, pipeline, ship and air, while the freight forwarder organises and commissions this transport in its own name.",correctIndex:1},{question:"According to the textbook, which goods is rail freight transport particularly suitable for?",options:["Light, perishable goods such as flowers or fresh seafood","Urgent small shipments","Bulk goods such as gravel or sand and dangerous goods","Only high-value goods"],explanation:"Rail freight transport is suitable for all piece and bulk goods, loose bulk goods (e.g. gravel, sand) and dangerous goods such as chemical products.",correctIndex:2},{question:"According to the textbook, which characteristic applies to air freight?",options:["It is the cheapest but also the slowest means of transport","It does not require any reloading","It is the fastest but most expensive means of transport","It is only suitable for bulk goods overseas"],explanation:"Air freight is the fastest means of transport with a dense network, but also the most expensive with low loading capacity – suitable for light, perishable or high-value goods.",correctIndex:2},{question:"How do consignment notes differ from documents of title?",options:["Consignment notes prove shipment, documents of title certify the right to the goods","Consignment notes are only used in shipping, documents of title only in road transport","Both terms refer to exactly the same document","Documents of title are only used for accompanying documents such as packing lists"],explanation:"Consignment notes are documents that serve as proof that the goods have been shipped. Documents of title (e.g. ocean bill of lading) work as a security and certify the right to the goods.",correctIndex:0},{question:"According to the textbook, how did CO2 emissions from road freight transport in Austria develop between 1990 and 2019 despite technical improvements?",options:["They fell by more than half thanks to significantly more efficient engines","They more than doubled because distances driven rose sharply","They stayed exactly the same despite more kilometres driven","They were reduced to zero thanks to electric lorries"],explanation:"CO2 emissions from Austrian road freight transport more than doubled between 1990 (4.1 million tonnes) and 2019 (8.8 million tonnes) – the savings per kilometre were more than outweighed by the increase in distances driven.",correctIndex:1}],"der-handel":[{question:"What fundamentally distinguishes retail from wholesale?",options:["Wholesale sells only to private individuals and end customers","Retail significantly processes the products before selling them to customers","Retail sells to end consumers, wholesale to other businesses","Wholesale only trades with companies in other countries"],explanation:"Retail mainly sells products to end consumers, while wholesale mainly supplies other companies such as retailers or manufacturers.",correctIndex:2},{question:"What fundamentally characterises trading companies?",options:["They make the products they sell themselves and sell them directly to customers","They only offer services such as advice","They process purchased raw materials into finished products","They buy products and sell them on without significant processing"],explanation:"Trading companies buy products from manufacturers and sell them on without significantly processing them.",correctIndex:3},{question:"What is the main difference between multi-channel and omni-channel solutions in trade?",options:["Multi-channel only refers to stationary retail without an online shop","With multi-channel all channels are technically linked, with omni-channel they exist separately side by side","There is no difference in content between the two terms","With omni-channel all channels are linked, with multi-channel they exist independently side by side"],explanation:"Omni-channel links all of a company's sales channels into one uniform customer experience, while with multi-channel the channels exist independently side by side.",correctIndex:3},{question:"According to the textbook, which statement about the importance of trade in Austria is true?",options:["Trade is Austria's second-largest employer, according to the WKÖ","Fewer than 5% of Austrian companies are active in the trade sector","Trade has hardly any influence on the look of towns and regions","Only a small minority of employees work in trade"],explanation:"According to the Austrian Chamber of Commerce, trade is Austria's second-largest employer; about a quarter of all employees work in trade.",correctIndex:0},{question:"Loopy has her homemade caramel sweets delivered from the production site to her Candy Store in the city centre. Which function of trade does this transport describe best?",options:["Bridging time (storage)","Bridging space (organising transport)","Quantity balancing (collecting and distributing)","Quality balancing (creating the range)"],explanation:"The function of bridging space ensures that products get from where they are made to where they are sold.",correctIndex:1},{question:"A retailer buys large quantities of Christmas decorations in June and stores them until October to sell them then. Which function of trade applies here?",options:["Bridging space (organising transport)","Quality balancing (creating the range)","Bridging time (storage)","Information function"],explanation:"Through storage, trade bridges the time between production and customers' needs.",correctIndex:2},{question:"Loopy buys a large quantity of chocolate from a wholesaler and then sells it individually or in small bags to her customers. Which function of trade is she fulfilling?",options:["Quantity balancing (distributing)","Bridging space (organising transport)","Bridging time (storage)","Communication function"],explanation:"Trade buys large quantities and distributes them to customers in small quantities that meet their needs – this is the quantity balancing function (collecting and distributing).",correctIndex:0},{question:"Which function of trade describes a trading company putting together a range that meets needs and being liable to customers for quality defects?",options:["Bridging space (organising transport)","Bridging time (storage)","Quantity balancing (collecting and distributing)","Quality balancing (creating the range)"],explanation:"Quality balancing (creating the range) means that trade checks the quality of the products and is responsible for exchange or repair if there are defects.",correctIndex:3},{question:"Which type of retail business offers a narrower but deeper range than a supermarket on a large sales area, mainly self-service, at low to average prices?",options:["Specialist and speciality shop","Specialist superstore","Department store","Convenience store"],explanation:"Specialist superstores focus on a specialised range with a wide choice within one product group, mostly self-service.",correctIndex:1},{question:"Loopy rents an empty shop for two weeks to present her new line of Christmas chocolates and create attention through word of mouth. What type of business is this?",options:["Factory outlet centre","Franchise business","Pop-up store","Specialist superstore"],explanation:"A pop-up store is a temporary shop in empty premises, meant to get people talking through its sudden appearance.",correctIndex:2},{question:"What is typical of a convenience store?",options:["Small shop with a limited range and long opening hours","Large shop with a very wide range and permanently low prices","A shop that sells only online, without any sales floor","A trading company that only sells brand surpluses at reduced prices"],explanation:"Convenience stores are small shops with a limited range (e.g. snacks, drinks, newspapers), long opening hours and usually somewhat higher prices.",correctIndex:0},{question:"How does a company's own online shop differ from an online marketplace such as Amazon?",options:["A company's own online shop is always more costly to set up than a marketplace","In its own shop only one company sells, on a marketplace several suppliers","Marketplaces only exist in wholesale between businesses","Online shops never use product pictures or reviews"],explanation:"In its own online shop only one company offers its products, while on an online marketplace several suppliers sell on a shared platform.",correctIndex:1},{question:"Loopy holds tasting evenings at her customers' homes where she sells her sweets directly. Which form of mobile trade is this?",options:["Street or market trade (e.g. market stall)","Delivery wholesale","Franchise","Direct sales (e.g. home party)"],explanation:"Direct sales include, for example, sales reps, sales trips and home parties, where goods are sold directly to the customer without a fixed location.",correctIndex:3},{question:"What is characteristic of cash-and-carry wholesale (self-service wholesale)?",options:["The wholesaler delivers the goods free of charge with its own fleet","The customer pays immediately and collects the goods themselves","The wholesaler rents shelves in other shops","Sales are made only through printed catalogues"],explanation:"In cash-and-carry wholesale, the customer pays for the goods immediately and handles the transport themselves; there is no delivery by the wholesaler.",correctIndex:1},{question:"What does a rack jobber do?",options:["Supplies retail businesses exclusively via catalogue orders","Sells only online to end consumers","Rents shelves in shops and looks after them itself","Is just another word for cash-and-carry wholesale"],explanation:"A rack jobber rents sales space or shelves in other retail businesses, stocks them with goods and looks after them itself; the retail business receives rent or a sales commission in return.",correctIndex:2},{question:"What characterises a franchise system?",options:["An independent company uses another company's concept and brand for a fee","Several trading companies join together to form a purchasing cooperative","A wholesaler supplies several independent retailers in the region at once","A company takes over all of a competitor's branches"],explanation:"A franchisee is an independent company that binds itself to a franchisor through a franchise agreement and in return receives a proven concept, an established brand and support.",correctIndex:0},{question:"What is a voluntary chain such as SPAR?",options:["An association in which all branches are owned and managed by a single company","Independent retailers jointly buy and advertise under one brand by contract","A model in which only the wholesaler looks after the shelves in the member shops","A purely digital sales model without its own branches or warehouses"],explanation:"In a voluntary chain, legally independent retailers contractually commit to joint advertising and joint purchasing under a common organisational brand.",correctIndex:1},{question:"How is a product's trade margin basically calculated?",options:["Purchase price minus production costs","Selling price divided by purchase price","Selling price minus purchase price","Fixed costs plus variable costs"],explanation:"The trade margin is the difference between the selling price and the purchase price; it must cover the trading company's costs and allow for a profit.",correctIndex:2}],"businessplan-2jg":[{question:"Loopy wants to apply for a loan to expand her Candy Store. According to the textbook, what is a business plan mainly used for?",options:["It presents the business idea and how it will be put into practice","It replaces a company's ongoing bookkeeping and annual financial statements","It is used only for the internal planning of employees' holidays","It is only needed by listed companies for their annual general meeting"],explanation:"A business plan presents the business idea and describes how it will be put into practice – a well-thought-out business plan is a key success factor, e.g. for convincing banks or investors.",correctIndex:0},{question:"According to the textbook, which item is NOT one of the components of a business plan?",options:["Executive summary","Payroll accounting","Financial planning","Opportunities and risks"],explanation:'According to the textbook, the components of a business plan are: executive summary, company, product/service, industry/market/competition, marketing, opportunities and risks, financial planning and implementation roadmap – "payroll accounting" is not listed as a separate component.',correctIndex:1},{question:"According to the textbook, how many pages should a business plan usually have?",options:["5 to 10 pages","50 to 60 pages","20 to 30 pages","100 to 120 pages"],explanation:"According to the textbook, a business plan should have approx. 20 to 30 pages; detailed documents such as CVs or brochures are added as an appendix.",correctIndex:2},{question:"According to the textbook, when is the executive summary of a business plan actually written, even though it comes at the start of the document?",options:["Before the business idea has even been decided","At the same time as the cover page","Right at the start, before all the other chapters of the plan","Only after the rest of the business plan is finished"],explanation:"The executive summary comes at the start of the business plan, but according to the textbook it is only written after the rest of the business plan is finished.",correctIndex:3},{question:"According to the textbook, which additional items should be added to a business plan?",options:["Cover page, table of contents and, if needed, a list of sources","An organisation chart of all competitors","A complete copy of the partnership agreement and the company register extract","A list of all insolvencies of past competitors in the industry"],explanation:"According to the textbook, a business plan should include a cover page, a table of contents and – if secondary market research is used – a list of sources.",correctIndex:0},{question:"According to the textbook, which four items make up the company and founder profile in the business plan?",options:["Financial planning and capital needs, marketing strategy, opportunities and risks, implementation roadmap","Business idea and vision, key people, legal form and company name, company location","Product and range policy, price policy, distribution policy, communication policy","Executive summary, cover page and table of contents, appendix, list of sources"],explanation:"According to the textbook, the company and founder profile covers business idea and vision, key people, legal form and company name, and the company location.",correctIndex:1},{question:"How does the textbook define a company vision?",options:["A detailed annual financial plan with concrete revenue and cost targets","A complete list of all location factors relevant to founding the company","A long-term picture of the company's development that inspires and motivates","A short-term operational measure for reaching targets in the current quarter"],explanation:"According to the textbook, a company vision is a picture of how the company should develop in the long term; it serves as inspiration and motivation (example in the textbook: Netflix).",correctIndex:2},{question:"Into which three types are location factors divided in the textbook?",options:["Personnel-related, finance-related and infrastructure-related location factors","Legal, tax-related and socio-cultural location factors","Short-term, medium-term and long-term location factors","Procurement-related, production-related and sales-oriented location factors"],explanation:"The textbook distinguishes procurement-related, production-related and sales-oriented location factors.",correctIndex:3},{question:"According to the textbook, why do supermarket chains usually set up near residential areas?",options:["To be as close as possible to their customers","Because rents are highest there","Because no competition is allowed there","Because tax rates are lowest in residential areas"],explanation:"According to the textbook, supermarket chains choose locations in residential areas to be as close as possible to their customers (an example of a sales-oriented location factor).",correctIndex:0},{question:"According to the textbook, what applies when weighting location factors in the scoring method?",options:["Every factor must be weighted exactly the same","All the weightings together must add up to 100%","No more than three location factors may be weighted","The weighting is done only after the location has been chosen"],explanation:"In the scoring method the location factors are weighted, and according to the textbook all the weightings together must add up to 100%.",correctIndex:1},{question:"According to the textbook, what are company goals with a time frame of 1 to 3 years called?",options:["Short-term goals","Long-term goals","Medium-term goals","Permanent goals"],explanation:"According to the textbook, goals with a time frame of 1 to 3 years are medium-term goals and concern the company's tactical direction.",correctIndex:2},{question:"According to the textbook, how can market potential also be stated in money terms?",options:["By dividing the number of competitors by the industry's revenue","By subtracting the fixed costs from the variable costs of the previous year","By multiplying last year's profit by the number of customers","By multiplying the theoretically possible sales volume by the price"],explanation:"According to the textbook, market potential can be stated in money terms by multiplying the amount that could theoretically be sold by the price of the product.",correctIndex:3},{question:'According to the textbook, what is meant by "indirect competition", e.g. in the ORF example?',options:["Companies that meet the same customer needs differently, e.g. streaming platforms","Channels that broadcast exactly the same programme at the same time to the same audience","Companies in a completely different industry with no link to the customer","Competitors that offer the same product only abroad and not in Austria"],explanation:"According to the textbook, indirect competition means companies that meet the same customer needs in a different way – in the ORF example, streaming platforms and social media instead of other TV channels.",correctIndex:0},{question:'According to the textbook, which four areas ("4 Ps") should be covered in the marketing part of a business plan?',options:["Personnel planning, process design, production planning, presentation techniques","Product and range policy, price and conditions policy, distribution policy, communication policy","Planning policy, inspection and control policy, presentation policy, record keeping","Price negotiation with suppliers, choice of partners and location, market positioning, staff planning"],explanation:"According to the textbook, the business plan must cover the 4 Ps in detail: product and range policy, price and conditions policy, distribution policy and communication policy.",correctIndex:1},{question:"According to the textbook, what is the analysis of external opportunities and risks in the business plan used for?",options:["To assess the internal strengths and weaknesses of the employees","To set the exact purchase price or rent of the business premises","To show potential investors how attractive the business idea is","To prepare the bookkeeping and annual accounts for the first business year"],explanation:"According to the textbook, listing the external opportunities and risks helps potential investors judge how attractive the business idea is.",correctIndex:2},{question:"According to the textbook, which two key questions does the financial planning in the business plan answer?",options:["How high is the competitors' revenue? How many employees does the company need?","Which legal form fits best? Where should the company's location be?","Who are the most important customers? Which advertising measures are planned?","How much capital is needed? How will it be raised through equity and/or debt?"],explanation:"According to the textbook, financial planning is the heart of a business plan and answers how much capital is needed and how it will be raised through equity and/or debt.",correctIndex:3},{question:`What is meant by the "critical path" in a business plan's implementation roadmap?`,options:["A chain of activities where delays can put the whole schedule at risk","The cheapest financing option for the whole start-up phase of the company","The route from the raw material supplier to the finished product","The list of all alternative locations with their particular risks"],explanation:"According to the textbook, the critical path is a chain of activities in the implementation roadmap where delays in single activities can put the whole schedule at risk.",correctIndex:0},{question:"According to the textbook, which of the following is NOT one of the business plan competitions for students mentioned?",options:["Business plan competition next generation","Junior Company Award","jugend innovativ","i2b (Business Plan Initiative)"],explanation:'The textbook mentions next generation, jugend innovativ and i2b (Business Plan Initiative) as business plan competitions for students – it does not mention a "Junior Company Award".',correctIndex:1}]}};export{e as default};
